\label{assoc2alg}
An {\bf associative 2-algebra} is a crossed-module of (finite dimensional) associative algebras. More precisely, ${\@fontswitch\relax\mathcal G}$ is the data of a pair of associative algebras ${\@fontswitch\relax\mathcal G}_0, \,{\@fontswitch\relax\mathcal G}_{-1}$ and an algebra homomorphism $t:{\@fontswitch\relax\mathcal G}_{-1}\rightarrow{\@fontswitch\relax\mathcal G}_0$ satisfying the following:
\begin{enumerate}
    \item ${\@fontswitch\relax\mathcal G}_{-1}$ is a ${\@fontswitch\relax\mathcal G}_0$-bimodule,
    \item $t$ is \textbf{two-sided ${\@fontswitch\relax\mathcal G}_0$-equivariant},
    \begin{equation}
        t(x\cdot y) = x t(y),\qquad t(y\cdot x)=t(y)x \label{algpeif1}
    \end{equation}
    for all $y\in{\@fontswitch\relax\mathcal G}_{-1},x\in{\@fontswitch\relax\mathcal G}_0$, and
    \item the \textbf{Peiffer identity} is satisfied,
    \begin{equation}
        t(y)\cdot y' = yy' = y\cdot t(y'),\label{algpeif2}
    \end{equation}
    where $y,y'\in{\@fontswitch\relax\mathcal G}_{-1}$.
\end{enumerate}
We call the latter two the {\it Peiffer conditions}. We denote an associative 2-algebra simply by ${\@fontswitch\relax\mathcal G}$, or by $({\@fontswitch\relax\mathcal G},\cdot)$ to emphasize the bimodule structure. Let $k$ denote the ground ring of the 2-vector space underlying ${\@fontswitch\relax\mathcal G}$. We call ${\@fontswitch\relax\mathcal G}$ {\bf unital} if there exists a unit map $\eta=(\eta_{-1},\eta_0):k \rightarrow {\@fontswitch\relax\mathcal G}$ such that
\begin{equation}
  \eta_{-1} y = y \eta_{-1} = y,  \quad \eta_0  x = x \eta_0 = x, \label{def:unity}
\end{equation}
for all $y\in{\@fontswitch\relax\mathcal G}_{-1},x\in{\@fontswitch\relax\mathcal G}_0$. Moreover, $t$ should respect the units, ie. $t (\eta_{-1}) = \eta_0$.

\label{bimodulecondition}
   If $t\neq 0$ were non-trivial then the Peiffer conditions, together with bimodularity, imply that
    \begin{equation}
        x\cdot(yy') = (x\cdot y)y',\qquad y(x\cdot y') = (y\cdot x)y',\qquad (yy')\cdot x=y(y'\cdot x) \nonumber
    \end{equation}
    for each $x\in {\@fontswitch\relax\mathcal G}_0,y,y'\in{\@fontswitch\relax\mathcal G}_{-1}$. This puts strong constraints on the algebra action $\cdot$, which is not necessarily imposed in the skeletal $t=0$ case.

The crossed-module model of a {\bf 2-group} $G$ is a group homomorphism $t:G_{-1}\rightarrow G_0$ together with an action $\rhd$ of $G_0$ on $G_{-1}$ such that the following conditions
\begin{equation}
    t(x\rhd y) = xt(y)x^{-1},\qquad (ty)\rhd y'=yy'y^{-1}\label{pfeif2}
\end{equation}
are satisfied for each $x\in G_0$ and $y,y'\in G_{-1}$. The first and second conditions are known respectively as the {\bf equivariance} and the {\bf Peiffer identity}.

Let $({\@fontswitch\relax\mathcal G}_{-1},\Delta_{-1})$ and $({\@fontswitch\relax\mathcal G}_0,\Delta_0')$ denote a pair of coassociative coalgebras with the coactions $\Delta_0^l$ and $\Delta_0^r$. We say that ${\@fontswitch\relax\mathcal G}_0$ forms a {\bf ${\@fontswitch\relax\mathcal G}_{-1}$-cobimodule} if the following {\bf cobimodularity conditions}
\begin{eqnarray}
    (\Delta_{-1}\otimes \operatorname{id})\circ \Delta_0^l &=& (\operatorname{id} \otimes\Delta_0^l)\circ\Delta_0^l,\nonumber\\
    (\operatorname{id} \otimes\Delta_{-1})\circ\Delta_0^r&=&(\Delta_0^r\otimes \operatorname{id})\circ\Delta_0^r,\nonumber\\
    (\operatorname{id}\otimes \Delta_0^r)\circ\Delta_0^l &=& (\Delta_0^l\otimes\operatorname{id})\circ\Delta_0^r\label{cohgrpd10}
\end{eqnarray}
are satisfied. In terms of commutative diagrams, we have
\begin{eqnarray}\nonumber
\begin{tikzcd}
&  {\@fontswitch\relax\mathcal G}_{0}  
\arrow[dl, "\Delta_0^l"]  \arrow[dr, "\Delta_0^l"] \\
 {\@fontswitch\relax\mathcal G}_{-1} \otimes {\@fontswitch\relax\mathcal G}_0 \arrow[dr, "\operatorname{id}\otimes \Delta_0^l"] & &{\@fontswitch\relax\mathcal G}_{-1} \otimes {\@fontswitch\relax\mathcal G}_{0} \arrow[dl, "\Delta_{-1}\otimes \operatorname{id}"]\\
&{\@fontswitch\relax\mathcal G}_{-1}\otimes {\@fontswitch\relax\mathcal G}_{-1}\otimes {\@fontswitch\relax\mathcal G}_{0} 
\end{tikzcd}, \nonumber\\
\begin{tikzcd}
&  {\@fontswitch\relax\mathcal G}_{0}  
\arrow[dl, "\Delta_0^r"]  \arrow[dr, "\Delta_{0}^r"] \\
 {\@fontswitch\relax\mathcal G}_{0} \otimes {\@fontswitch\relax\mathcal G}_{-1} \arrow[dr, "\Delta_0^r\otimes\operatorname{id}"] & &{\@fontswitch\relax\mathcal G}_{0} \otimes {\@fontswitch\relax\mathcal G}_{-1} \arrow[dl, "\operatorname{id}\otimes \Delta_{-1}"]\\
&{\@fontswitch\relax\mathcal G}_{0}\otimes {\@fontswitch\relax\mathcal G}_{-1}\otimes {\@fontswitch\relax\mathcal G}_{-1} 
\end{tikzcd}\nonumber \\
\begin{tikzcd}
&  {\@fontswitch\relax\mathcal G}_{0}  
\arrow[dl, "\Delta_0^r"]  \arrow[dr, "\Delta^l_{0}"] \\
 {\@fontswitch\relax\mathcal G}_{0} \otimes {\@fontswitch\relax\mathcal G}_{-1} \arrow[dr, "\Delta_0^l\otimes\operatorname{id}"'] & &{\@fontswitch\relax\mathcal G}_{-1} \otimes {\@fontswitch\relax\mathcal G}_{0} \arrow[dl, "\operatorname{id}\otimes\Delta_0^r "]\\
&{\@fontswitch\relax\mathcal G}_{-1}\otimes {\@fontswitch\relax\mathcal G}_0\otimes {\@fontswitch\relax\mathcal G}_{-1} 
\end{tikzcd}
\end{eqnarray}

\label{coassoc2coalg}
A {\bf coassociative 2-coalgebra} $({\@fontswitch\relax\mathcal G},\Delta)$ is a coalgebra homomorphism $t:{\@fontswitch\relax\mathcal G}_{-1}\rightarrow{\@fontswitch\relax\mathcal G}_0$ such that
\begin{enumerate}
    \item ${\@fontswitch\relax\mathcal G}_0$ is a ${\@fontswitch\relax\mathcal G}_{-1}$-cobimodule,
    \item $t$ is \textbf{coequivariant} 

    \begin{equation}
        D_t^+\circ\Delta_{-1}= \Delta_0\circ t, \label{cohgrpd+} 
    \end{equation}
    where we have introduced a convenient tensor notation for the induced $t$-map
    \begin{equation}
        D_t^\pm := t\otimes 1 \pm 1\otimes t \nonumber
    \end{equation}
in terms of the graded sum.  This condition is encoded by the following commutative diagram.
\begin{eqnarray}\label{diag:coequiv}
\begin{tikzcd}
&  {\@fontswitch\relax\mathcal G}_{-1}  
\arrow[dl, "t"]  \arrow[dr, "\Delta_{-1}"] \\
 {\@fontswitch\relax\mathcal G}_0 \arrow[dr, "\Delta_0"] & &{\@fontswitch\relax\mathcal G}_{-1}\otimes {\@fontswitch\relax\mathcal G}_{-1} \arrow[dl, "D_t^+"]\\
&
{\@fontswitch\relax\mathcal G}_{0}\otimes {\@fontswitch\relax\mathcal G}_{-1}\oplus {\@fontswitch\relax\mathcal G}_{-1}\otimes {\@fontswitch\relax\mathcal G}_0
\end{tikzcd}
\end{eqnarray}   
    \item the {\bf coPeiffer identity}
    \begin{equation}
        (t\otimes\operatorname{id})\circ\Delta_0^l = \Delta_0' = (\operatorname{id}\otimes t)\circ\Delta_0^r, \label{cohgrpd-} 
    \end{equation}
     which in particular means that we must necessarily have
    \begin{equation}
        D_t^-\Delta_0 =(t\otimes\operatorname{id})\circ\Delta_0^l - (\operatorname{id}\otimes t)\circ\Delta_0^r  =0.\nonumber
    \end{equation}    
It is encoded in the following commutative diagram    
    \begin{eqnarray}\label{diag:coPid1}
\begin{tikzcd}
&  {\@fontswitch\relax\mathcal G}_{0}\otimes {\@fontswitch\relax\mathcal G}_{0}  
  \\
{\@fontswitch\relax\mathcal G}_0\otimes {\@fontswitch\relax\mathcal G}_{-1}\arrow[ur, "\operatorname{id}\otimes t"]   & &{\@fontswitch\relax\mathcal G}_{-1}\otimes {\@fontswitch\relax\mathcal G}_{0} \arrow[ul, "t\otimes \operatorname{id}"]\\
&
{\@fontswitch\relax\mathcal G}_{0}\arrow[ul, "\Delta_0^r"] \arrow[uu,"\Delta_0'"]  \arrow[ur, "\Delta_0^l"]
\end{tikzcd}.
\end{eqnarray}


\end{enumerate}
We call $({\@fontswitch\relax\mathcal G},\Delta)$ {\bf counital} if there is a {counit} map $\epsilon=(\epsilon_{-1},\epsilon_0):{\@fontswitch\relax\mathcal G}\rightarrow k $ such that 
\begin{eqnarray}
    \operatorname{id}=(\operatorname{id}\otimes \epsilon_{-1})\circ\Delta_{-1},&\quad& \operatorname{id} = (\epsilon_{-1}\otimes \operatorname{id})\circ\Delta_{-1},\nonumber\\
    \operatorname{id}=(\epsilon_{-1}\otimes \operatorname{id})\circ\Delta_0^l, &\quad& \operatorname{id} =(\operatorname{id}\otimes \epsilon_{-1})\circ\Delta_0^r.\label{counit}
\end{eqnarray}
Moreover, $\epsilon$ should respect the $t$-map such that $\epsilon_{-1} = \epsilon_0\circ t $.

\label{comp-const}
Similar to the 2-algebra case, if $t\neq0$ were not trivial, then we could have the following conditions
 \begin{eqnarray}
     (\operatorname{id}\otimes \Delta_0')\circ \Delta_0^l = (\Delta_0^l\otimes \operatorname{id})\circ \Delta_0',\nonumber\\
     (\Delta_0'\otimes\operatorname{id})\circ \Delta_0^r= (\operatorname{id}\otimes \Delta_0^r)\circ \Delta_0',\nonumber\\
     (\operatorname{id}\otimes\Delta_0^l)\circ \Delta_0' = (\Delta_0^r\otimes \operatorname{id})\circ \Delta_0'\label{cobimodu}
 \end{eqnarray}
between the coproducts $\Delta_0$ and $\Delta_0'$. By making use of the Sweedler notation  \eqref{sweed}, \eqref{deg0sweed}, the coequivariance and the coPeiffer identities translate to
\begin{equation}\label{condcop}
\begin{cases}ty_{(1)} = (ty)_{(1)}^r \\ ty_{(2)} = (ty)_{(2)}^l\end{cases},\qquad \begin{cases} \bar x_{(1)} = t x_{(1)}^l = x_{(1)}^r \\ \bar x_{(2)} = x_{(2)}^l = tx_{(2)}^r\end{cases}.
\end{equation}
When combined, they give $\widebar{ty}_{(1)} = ty_{(1)}, \widebar{ty}_{(2)} = ty_{(2)}$ which will become important later. In the skeletal case, the constraints involving $t$ drop.

\label{assoc2bialg}
The tuple $({\@fontswitch\relax\mathcal G},\cdot,\Delta)$ is an {\bf associative 2-bialgebra} iff $({\@fontswitch\relax\mathcal G},\cdot)$ is an associative 2-algebra and $({\@fontswitch\relax\mathcal G},\Delta)$ is a coassociative 2-coalgebra such that the two structures are mutually compatible; namely $\Delta$ satisfies \eqref{2algcoprod}.

We call $({\@fontswitch\relax\mathcal G},\cdot,\eta,\Delta,\epsilon)$ {\bf unital} if $({\@fontswitch\relax\mathcal G},\cdot,\eta)$ and $({\@fontswitch\relax\mathcal G},\Delta,\epsilon)$ are respectively unital and counital.

In general, given an ordinary 1-bialgebra $G$, we can form its associated trivial 2-bialgebra ${\@fontswitch\relax\mathcal G} = G\xrightarrow{\operatorname{id}}G$ in analogy with the above. Moreover, it is clear that any bialgebra homomorphism $f:G\rightarrow G'$ extends to a 2-bialgebra homomorphism $f\oplus f: {\@fontswitch\relax\mathcal G}\rightarrow {\@fontswitch\relax\mathcal G}'$, whose graded components are just copies of $f$. We therefore have an embedding
\begin{equation}
    \text{Bialg}_\text{ass}\hookrightarrow \text{2Bialg}_\text{ass}\label{2algembed}
\end{equation}
of the category of associative bialgebras into the category of associative 2-bialgebras. This is a "quantum" version of an analogous result for Lie 2-bialgebras stated in {\it Remark 3.11} of \cite{Bai:2007}.

The canonical \textbf{coadjoint action} of ${\@fontswitch\relax\mathcal G}$ on ${\@fontswitch\relax\mathcal G}^*$ is specified in terms of three components, $\bar\rhd=((\rhd_0,\rhd_{-1}),\Upsilon)$ given by 
\begin{eqnarray}
    \rhd_0:{\@fontswitch\relax\mathcal G}_0\rightarrow \operatorname{End}{\@fontswitch\relax\mathcal G}_0^*,&\qquad& \langle g,xx'\rangle = -\langle x\rhd_0 g,x'\rangle,\nonumber\\
    \rhd_{-1}:{\@fontswitch\relax\mathcal G}_0\rightarrow \operatorname{End}{\@fontswitch\relax\mathcal G}_{-1}^*,&\qquad& \langle f,x\cdot y\rangle = -\langle x\rhd_{-1} f,y\rangle,\nonumber\\
    \Upsilon:{\@fontswitch\relax\mathcal G}_{-1}\rightarrow \operatorname{Hom}({\@fontswitch\relax\mathcal G}_{-1}^*,{\@fontswitch\relax\mathcal G}_0^*),&\qquad& \langle f,y\cdot x\rangle = -\langle \Upsilon_yf, x\rangle.\label{coadj0}
\end{eqnarray}

\label{skelqd}
Note that in the skeletal case $t,t^*=0$, the crossed relations  \eqref{comprel1}, \eqref{comprel2} reduce to just two non-trivial equations. These are given by
\begin{eqnarray}
    x\rhd_{-1}(ff') &=& (x^r_{(1)} \rhd_0 f_{(1)}^l)\cdot^*(\Upsilon_{x^r_{(2)}\lhd_0f_{(2)}^l} f')+ (\Upsilon_{x^l_{(1)}}f_{(1)}^r) \cdot^*(\Upsilon_{x^l_{(2)}\tilde\Upsilon_{f_{(2)}^r}}f')\nonumber\\
    &\equiv & (x_{(1)}\bar\rhd f_{(1)})\cdot^* ((x_{(2)}\bar\lhd f_{(2)})\bar\rhd f'),\nonumber\\
    (xx') \lhd_{-1} f &=&  (x\tilde\Upsilon_{x'^r_{(1)}\rhd_0 f^l_{(1)}})\cdot (x'^r_{(2)} \lhd_0f^l_{(2)}) + (x \tilde\Upsilon_{\Upsilon_{x'^l_{(1)}}f^r_{(1)}})\cdot (x'^l_{(2)} \tilde\Upsilon_{f^r_{(2)}})\nonumber\\
    &\equiv& (x\bar\lhd (x_{(1)}'\bar\rhd f_{(1)}))\cdot (x_{(2)}\bar\lhd f_{(2)}),\label{skelcomprel} 
\end{eqnarray}
where we have used a convenient notation for brevity. One may notice that these are precisely the usual crossed relations for a quantum double group (cf. \cite{Majid:1996kd}) of a semidirect product 2-bialgebra ${\@fontswitch\relax\mathcal G}_{-1}\rtimes {\@fontswitch\relax\mathcal G}_0$, where ${\@fontswitch\relax\mathcal G}_{-1}$ is nuclear.

This is a direct computation. By the equality in the second row of  \eqref{genpeif}, we have
\begin{equation}
    \langle f, y\cdot ty'\rangle=-\langle t^*\Upsilon_yf,y'\rangle=-\langle (ty)\rhd_{-1}f,y'\rangle = \langle f,ty\cdot y'\rangle,\nonumber
\end{equation}
giving $ty\cdot y' = y\cdot ty'$. Now by the fact that $t$ is an algebra homomorphism, we have
\begin{eqnarray}
    \langle (ty)\rhd_0 g,ty'\rangle &=& -\langle g,(ty)(ty')\rangle = -\langle g,t(yy')\rangle,\nonumber\\
    \langle \Upsilon_y(t^*g),ty'\rangle &=& -\langle t^*g,y\cdot ty'\rangle=-\langle g,t(y\cdot ty')\rangle,\nonumber
\end{eqnarray}
for which the first row of  \eqref{genpeif} states $yy' = y\cdot ty'$. Altogether yields
\begin{equation}
    yy' = y\cdot t(y') = t(y)\cdot y'\nonumber
\end{equation}
for any $y,y'\in {\@fontswitch\relax\mathcal G}_{-1}$, which is precisely the Peiffer identity on ${\@fontswitch\relax\mathcal G}$. Similarly, if $\bar\lhd$ is the coadjoint representation then  \eqref{genpeif} reproduces the Peiffer identity on ${\@fontswitch\relax\mathcal G}^*$.

\label{2qd}

Suppose a (unital) 2-bialgebra $({\@fontswitch\relax\mathcal K}={\@fontswitch\relax\mathcal K}_{-1}\xrightarrow{T}{\@fontswitch\relax\mathcal K}_0,\hat\cdot)$ factorizes into two (unital) sub-2-bialgebras ${\@fontswitch\relax\mathcal G},{\@fontswitch\relax\mathcal H}$, meaning that there is a span of inclusions,
\begin{equation}
    {\@fontswitch\relax\mathcal G}\xhookrightarrow{\iota}{\@fontswitch\relax\mathcal K}\xhookleftarrow{\jmath}{\@fontswitch\relax\mathcal H}, \label{span}
\end{equation} 
such that $\hat\cdot\circ (\iota\otimes\jmath)$ is an isomorphism of 2-vector spaces and such that  the 2-sub-bialgebras ${\@fontswitch\relax\mathcal G},{\@fontswitch\relax\mathcal H}$ are dually paired, with their $t$-maps satisfying $\langle t_{\@fontswitch\relax\mathcal G}\cdot,\cdot\rangle = \langle \cdot,t_{\@fontswitch\relax\mathcal H}\cdot\rangle$. Then $({\@fontswitch\relax\mathcal G},{\@fontswitch\relax\mathcal H})$ is a matched pair and ${\@fontswitch\relax\mathcal K}\cong {\@fontswitch\relax\mathcal G} \bar{\bowtie} {\@fontswitch\relax\mathcal H}$.

Let ${\@fontswitch\relax\mathcal K}={\@fontswitch\relax\mathcal K}_{-1}\xrightarrow{T}{\@fontswitch\relax\mathcal K}_0$ be a 2-bialgebra factorizing into two 2-subbialgebras ${\@fontswitch\relax\mathcal G},{\@fontswitch\relax\mathcal H}$, with typical elements $w\in {\@fontswitch\relax\mathcal K}_0$ and $e\in {\@fontswitch\relax\mathcal K}_{-1}$. Its 2-algebra structure $\hat\cdot$ contains a multiplication $ww'$ in ${\@fontswitch\relax\mathcal K}_0$ and a ${\@fontswitch\relax\mathcal K}_0$-bimodule structure $w\hat\cdot e,e\hat\cdot w$ on ${\@fontswitch\relax\mathcal K}_{-1}$, which are both associative. Since  \eqref{span} is a span of 2-vector spaces, we have
\begin{equation}
    T\circ (\iota_{-1}\otimes \jmath_{-1}) = (\iota_0\circ t_{\@fontswitch\relax\mathcal G})\otimes (\jmath_0\circ t_{\@fontswitch\relax\mathcal H}) = (\iota_0\otimes \jmath_0)\circ (t_{\@fontswitch\relax\mathcal G}\otimes t_{\@fontswitch\relax\mathcal H}), \nonumber
\end{equation}
where $t_G,t_H$ are the $t$-maps in ${\@fontswitch\relax\mathcal G},{\@fontswitch\relax\mathcal H}$ respectively, and $\iota_{-1},\iota_0$ are the graded components of the inclusion $\iota$; similarly for $\jmath$. 


We now separate the bimodule structure $\hat\cdot$ into components according to the span  \eqref{span},
\begin{equation}
    \hat\rhd\equiv \hat\cdot|_{\operatorname{im}(\iota_0\otimes \jmath_{-1})},\qquad \hat\Upsilon\equiv \hat\cdot|_{\operatorname{im}(\iota_{-1}\otimes \jmath_0)},\nonumber 
\end{equation}
then for $e=\iota_{-1}(y),e'=\jmath_{-1}(g)$ where $y\in G_{-1},g\in H_{-1}$ we have
\begin{equation}
    (T\iota_{-1}(y))\hat\rhd \jmath_{-1}(g) = \iota_0(t_{\@fontswitch\relax\mathcal G} y)\hat\rhd \jmath_{-1}(g).\nonumber
\end{equation}
By the Peiffer identity in ${\@fontswitch\relax\mathcal K}$, this should read as a left-multiplication of $y$ on $g$. We lift this action along $t_{\@fontswitch\relax\mathcal H}$ to create a map $\hat\Upsilon_y:{\@fontswitch\relax\mathcal H}_0\rightarrow {\@fontswitch\relax\mathcal H}_{-1}$, for which $\hat\Upsilon_y(t_{\@fontswitch\relax\mathcal H} g)$ denotes the left-multiplicaion of $y$ by $g$. Similarly we have the lift $\hat\Upsilon_g:{\@fontswitch\relax\mathcal G}_0\rightarrow {\@fontswitch\relax\mathcal G}_{-1}$ of the right-multiplication of $g$ on $y$.

Provided we identify $\hat\Upsilon_{y\otimes g} = \Upsilon_y\otimes \tilde\Upsilon_g$, the Peiffer conditions in ${\@fontswitch\relax\mathcal K}$ are then equivalent to the 2-representation properties  \eqref{ddequivar}, \eqref{genpeif}. In particular, the multiplication $y\cdot g=\Upsilon_y(t^*g) = (ty)\tilde\Upsilon_g$ is given by the generalized Peiffer identity as shown in {\bf Proposition \ref{gen2alg}}.

\smallskip

Now we prove that  \eqref{span} is in fact a span of 2-algebras. Due to the linear isomorphsm $\hat\cdot\circ(\iota\otimes\jmath)$, there exists a tuple of well-defined linear maps $\Psi = (\Psi_0,\Psi_{-1};\bar\Psi): {\@fontswitch\relax\mathcal G}\otimes {\@fontswitch\relax\mathcal H}\rightarrow {\@fontswitch\relax\mathcal H}\otimes {\@fontswitch\relax\mathcal G}$, called the {\bf braided transposition}, such that
\begin{eqnarray}
    \iota_0(x)\cdot\jmath_0(f) = \cdot \circ (\jmath_0\otimes\iota_0)\circ \Psi_0(x\otimes f),\nonumber\\
    \iota_0(x)\hat\rhd \jmath_{-1}(g) = \hat\Upsilon \circ(\jmath_{-1}\otimes\iota_0)\circ \Psi^r_{-1}(x\otimes g),\nonumber\\
    \iota_{-1}(y)\hat\Upsilon \jmath_0(f)= \hat\lhd \circ(\jmath_0\otimes\iota_{-1}) \circ \Psi^l_{-1}(y\otimes f),\nonumber\\
    \iota_{-1}(y)\cdot \jmath_{-1}(g) = \cdot \circ(\jmath_{-1}\otimes\iota_{-1})\circ\bar\Psi(y\otimes g),\nonumber
\end{eqnarray}
where $\Psi_{-1} = \Psi_{-1}^l+\Psi_{-1}^r$ and $x\in {\@fontswitch\relax\mathcal G}_0,y\in {\@fontswitch\relax\mathcal G}_{-1},f\in {\@fontswitch\relax\mathcal H}_0,g\in {\@fontswitch\relax\mathcal H}_{-1}$. Due to Peiffer conditions on ${\@fontswitch\relax\mathcal K}$, these braiding maps are not independent and must satisfy
\begin{gather}
    (t_{\@fontswitch\relax\mathcal H}\otimes 1)\circ \Psi_{-1}^r=\Psi_0\circ(1\otimes t_{\@fontswitch\relax\mathcal H}),\qquad (1\otimes t_{\@fontswitch\relax\mathcal G})\circ \Psi_{-1}^l = \Psi_0\circ(t_{\@fontswitch\relax\mathcal G}\otimes 1),\nonumber\\
    \Psi_{-1}^r\circ(t_{\@fontswitch\relax\mathcal G}\otimes 1) = \bar\Psi =\Psi_{-1}^l\circ(1\otimes t_{\@fontswitch\relax\mathcal H}).\nonumber
\end{gather}
By collecting all of the graded components of $\Psi$ in accordance with the shorthand notation $z=(y,x)\in {\@fontswitch\relax\mathcal G},h=(g,f) \in {\@fontswitch\relax\mathcal H}$, the definition  of $\Psi$ can be concisely written as
\begin{equation}
    \iota(z)~\hat\cdot~\jmath(h) = \hat\cdot\circ (\jmath\otimes\iota) \circ \Psi(z\otimes h),\label{braid}
\end{equation} 
and the relations between its components is summarized as
\begin{equation}
    T'\circ\Psi_{-1} = \Psi_0\circ T,\qquad \bar\Psi = \Psi_{-1}\circ T,\label{braidcomprel}
\end{equation}
where $T' = t_{\@fontswitch\relax\mathcal H}\otimes t_{\@fontswitch\relax\mathcal G}$ is the $t$-map of the 2-bialgebra ${\@fontswitch\relax\mathcal K}'\cong{\@fontswitch\relax\mathcal H}\otimes{\@fontswitch\relax\mathcal G}$ with ${\@fontswitch\relax\mathcal G},{\@fontswitch\relax\mathcal H}$ swapped in the span  \eqref{span}.  \eqref{braidcomprel} then implies in particular that $\Psi:{\@fontswitch\relax\mathcal K}\rightarrow {\@fontswitch\relax\mathcal K}'$ is a 2-vector space homomorphism. 

\medskip

We now proceed formally as in the 1-bialgebra case \cite{Majid:1996kd,Majid:1994nw}. The associativity in ${\@fontswitch\relax\mathcal K}$ is
\begin{eqnarray}
    (\iota(z)\hat\cdot\iota(z'))\hat\cdot\jmath(h)&=& \iota(z)\hat\cdot(\iota(z')\hat\cdot\jmath(h)),\nonumber\\
    (\iota(z)\hat\cdot\jmath(h))\hat\cdot \jmath(h')&=& \iota(z)\hat\cdot(\jmath(h)\hat\cdot \jmath(h')),\nonumber
\end{eqnarray}
which yields the {\bf 2-braiding relations}
\begin{eqnarray}
     \Psi \circ(\hat\cdot \otimes \operatorname{id}) &=& (\operatorname{id}\otimes \hat\cdot)\circ \Psi_{12}\circ \Psi_{23},\nonumber\\
     \Psi\circ(\operatorname{id}\otimes \hat\cdot) &=& (\hat\cdot\otimes \operatorname{id})\circ \Psi_{23}\circ \Psi_{12}.\label{2yb1}
\end{eqnarray}
This then allows us to define the actions
\begin{eqnarray}
    \bar\rhd &=& (\operatorname{id}\otimes \epsilon)\circ\Psi:{\@fontswitch\relax\mathcal G}\otimes {\@fontswitch\relax\mathcal H}\rightarrow {\@fontswitch\relax\mathcal H},\nonumber\\
    \bar\lhd &=& (\epsilon\otimes\operatorname{id})\circ\Psi:{\@fontswitch\relax\mathcal G}\otimes {\@fontswitch\relax\mathcal H}\rightarrow {\@fontswitch\relax\mathcal G},\nonumber
\end{eqnarray}
where $\epsilon$ denotes the counit map. Applying $\operatorname{id}\otimes \epsilon$ and $\epsilon\otimes\operatorname{id}$ respectively to the first and second equation of  \eqref{2yb1} implies that $\bar\rhd,\bar\lhd$ respect the semidirect product structures ${\@fontswitch\relax\mathcal G}_{-1}\rtimes {\@fontswitch\relax\mathcal G}_0,{\@fontswitch\relax\mathcal H}_{-1}\rtimes {\@fontswitch\relax\mathcal H}_0$, respectively. Together with our above result,  \eqref{span} is in fact a span of 2-algebras.

We now prove that  \eqref{span} is actually a span of 2-bialgebras, which proves the theorem. Applying $\epsilon\otimes\operatorname{id}$ and $\operatorname{id}\otimes \epsilon$ respectively to the first and second  \eqref{2yb1} yields
\begin{equation}
    (z\cdot z')\bar\lhd h = \hat\cdot (z\bar\lhd \Psi(z'\otimes h)),\qquad z\bar\rhd(h\cdot h') = \hat\cdot(\Psi(z\otimes h)\hat\rhd h').\label{2repbruh}
\end{equation}
We now take the coproduct $\Delta_K:{\@fontswitch\relax\mathcal K}\rightarrow {\@fontswitch\relax\mathcal K}^{2\otimes}$ on ${\@fontswitch\relax\mathcal K}$, given in components and Sweedler notation (see  \eqref{grpdcoprod}, \eqref{sweed}) by
\begin{equation}
    (\Delta_{{\@fontswitch\relax\mathcal K}})_{-1}(e) = e_{(1)}\otimes e_{(2)},\qquad (\Delta_{{\@fontswitch\relax\mathcal K}})_0(w) = w_{(1)}^l\otimes w^l_{(2)}+ w_{(1)}^r\otimes w_{(2)}^r;\nonumber
\end{equation}
note $w_{(1)}^l,w_{(2)}^r\in {\@fontswitch\relax\mathcal K}_{-1}$. With the span  \eqref{span}, we can write $w=\iota_0(x)\jmath_0(f),e=\iota_{-1}(y)\jmath_{-1}(g)$ for some appropriate elements $x,f,y,g$ such that
\begin{eqnarray}
     (\Delta_{{\@fontswitch\relax\mathcal K}})_{-1}(y,g) &=& (y_{(1)}\otimes g_{(1)})\otimes (y_{(2)}\otimes g_{(2)}),\nonumber\\
     (\Delta_{{\@fontswitch\relax\mathcal K}}^l)_0(x,f) &=& (x^l_{(1)}\otimes f^l_{(1)})\otimes (x^l_{(2)}\otimes f^l_{(2)}),\nonumber\\
     (\Delta_{{\@fontswitch\relax\mathcal K}}^r)_0(x,f) &=& (x^r_{(1)}\otimes f^r_{(1)})\otimes (x^r_{(2)}\otimes f^r_{(2)}).\nonumber
\end{eqnarray}
This then allows us to define coproducts on ${\@fontswitch\relax\mathcal G},{\@fontswitch\relax\mathcal H}$ by
\begin{eqnarray}
    (\Delta_{{\@fontswitch\relax\mathcal G}})_{-1}(y) = y_{(1)}\otimes y_{(2)},&\qquad&(\Delta_{{\@fontswitch\relax\mathcal G}})_0(x) = x^l_{(1)}\otimes x^l_{(2)}+x_{(1)}^r\otimes x_{(2)}^r,\nonumber\\
    (\Delta_{{\@fontswitch\relax\mathcal H}})_{-1}(g) = g_{(1)}\otimes g_{(2)},&\qquad&(\Delta_{{\@fontswitch\relax\mathcal H}})_0(f) = f^l_{(1)}\otimes f^l_{(2)}+f^r_{(1)}+f^r_{(2)},\nonumber
\end{eqnarray}
whence $\Delta_{{\@fontswitch\relax\mathcal K}} = \Delta_{{\@fontswitch\relax\mathcal G}\otimes {\@fontswitch\relax\mathcal H}}$, which implies that $\hat\cdot\circ (\iota\otimes\jmath)$ and $\hat\cdot\circ(\jmath\otimes\iota)$ by construction respects the coproducts. 

As such, $\Psi$ is a 2-coalgebra map. In particular, we have
\begin{equation}
    \Delta_{{\@fontswitch\relax\mathcal K}}\circ\Psi = (\Psi\otimes\Psi)\circ\Delta_{{\@fontswitch\relax\mathcal K}'},\qquad (\epsilon\otimes \epsilon)\circ\Psi = \epsilon\otimes\epsilon\label{2repbruh'}
\end{equation}
where ${\@fontswitch\relax\mathcal K}'$ is the 2-bialgebra with ${\@fontswitch\relax\mathcal G},{\@fontswitch\relax\mathcal H}$ swapped in the span  \eqref{span}. An application of $\epsilon\otimes \operatorname{id}\otimes \epsilon\otimes\operatorname{id}$ and $\operatorname{id}\otimes \epsilon\otimes \operatorname{id}\otimes \epsilon$ to  \eqref{2repbruh'} gives
\begin{equation}
    \Delta_{{\@fontswitch\relax\mathcal G}} \circ \bar\lhd = (\bar\lhd\otimes\bar\lhd) \circ \Delta_{{\@fontswitch\relax\mathcal K}},\qquad \Delta_{{\@fontswitch\relax\mathcal H}} \circ\bar\rhd = (\bar\rhd\otimes\bar\rhd)\circ\Delta_{{\@fontswitch\relax\mathcal K}},\nonumber
\end{equation}
which ensures that $\bar\rhd,\bar\lhd$ are 2-coalgebra maps. 

Now applying $\epsilon\otimes\operatorname{id}\otimes\operatorname{id}\otimes \epsilon$ and $\operatorname{id}\otimes\epsilon\otimes\epsilon\otimes\operatorname{id}$ to  \eqref{2repbruh'} yields
\begin{eqnarray}
     z_{(1)}\bar\lhd h_{(1)} \otimes z_{(2)}\bar\rhd h_{(2)} &=& \tau\circ\Psi(z\otimes h),\nonumber\\
     z_{(1)}\bar\rhd h_{(1)} \otimes z_{(2)}\bar\lhd h_{(2)} &=& \Psi(z\otimes h).\nonumber
\end{eqnarray}
Using the second equation, together with  \eqref{2repbruh}, gives  \eqref{grpdunit} and
\begin{eqnarray}
     z\bar\rhd(h\hat\cdot|_{\@fontswitch\relax\mathcal H} h') &=& \hat\cdot((z_{(1)}\bar\rhd h_{(1)}\otimes z_{(2)}\bar\lhd h_{(2)})\hat\rhd h')= (z_{(1)}\bar\rhd h_{(1)})\hat\cdot|_{\@fontswitch\relax\mathcal H}((z_{(2)}\hat\lhd h_{(2)})\bar\rhd h'),\nonumber\\
     (z\hat\cdot|_{\@fontswitch\relax\mathcal G} z')\bar\lhd h &=& \hat\cdot(z\bar\lhd (z'_{(1)}\bar\rhd h_{(1)}\otimes z'_{(2)}\bar\lhd h_{(2)}))= (z\bar\lhd (z'_{(1)}\bar\rhd h_{(1)}))\hat\cdot|_{\@fontswitch\relax\mathcal G}(z'_{(2)}\hat\lhd h_{(2)}),\nonumber
\end{eqnarray}
which are precisely the matched pair conditions  \eqref{comprel1}, \eqref{comprel2} for $\hat\cdot|_{\@fontswitch\relax\mathcal G}=\cdot,\hat\cdot|_{{\@fontswitch\relax\mathcal H}}=\cdot^*$. On the other hand, using the first equation gives  \eqref{crossrel}. Thus  \eqref{span} is a span of 2-bialgebras and so $K \cong {\@fontswitch\relax\mathcal G} \bar{\bowtie}{\@fontswitch\relax\mathcal H}$.

\label{2Rdef}
A quasitriangular \textbf{2-$R$-matrix} of a 2-bialgebra $({\@fontswitch\relax\mathcal G},\cdot,\Delta)$ is an element ${\@fontswitch\relax\mathcal R}\in{\@fontswitch\relax\mathcal G}\otimes{\@fontswitch\relax\mathcal G}$ \textit{of total degree -1}, consisting of the graded components
\begin{equation}
    {\@fontswitch\relax\mathcal R}^l \in {\@fontswitch\relax\mathcal G}_{-1}\otimes {\@fontswitch\relax\mathcal G}_0,\qquad {\@fontswitch\relax\mathcal R}^r\in{\@fontswitch\relax\mathcal G}_0\otimes {\@fontswitch\relax\mathcal G}_{-1},\nonumber
\end{equation}
such that the following identities are satisfied:
\begin{enumerate}
    \item the {\bf compatibility with the coproduct}
    \begin{gather}
    (\Delta_0^l \otimes \operatorname{id}) {\@fontswitch\relax\mathcal R}^r = {\@fontswitch\relax\mathcal R}^l_{13}\cdot_l{\@fontswitch\relax\mathcal R}^r_{23},\qquad (\Delta_0^r\otimes \operatorname{id}) {\@fontswitch\relax\mathcal R}^r = {\@fontswitch\relax\mathcal R}^r_{13}\cdot_r{\@fontswitch\relax\mathcal R}^l_{23},\nonumber\\
    (\operatorname{id}\otimes\Delta_0^l) {\@fontswitch\relax\mathcal R}^l = {\@fontswitch\relax\mathcal R}^l_{13}\cdot_r{\@fontswitch\relax\mathcal R}^r_{12},\qquad (\operatorname{id}\otimes \Delta_0^r) {\@fontswitch\relax\mathcal R}^l = {\@fontswitch\relax\mathcal R}^r_{13}\cdot_l{\@fontswitch\relax\mathcal R}^l_{12}, \label{def2R1}
    \end{gather}
    \item the {\bf coproduct permutation identity}
    \begin{equation}
      {\@fontswitch\relax\mathcal R}^r\Delta_0^r(x)=(\sigma\circ \Delta_0^l(x)){\@fontswitch\relax\mathcal R}^r,\qquad  {\@fontswitch\relax\mathcal R}^l\Delta_0^l(x)=(\sigma\circ\Delta_0^r(x)){\@fontswitch\relax\mathcal R}^l
    \label{def2R2}                   
\end{equation}
for each $x\in{\@fontswitch\relax\mathcal G}_0$, where $\sigma:{\@fontswitch\relax\mathcal G}\otimes{\@fontswitch\relax\mathcal G}\rightarrow {\@fontswitch\relax\mathcal G}\otimes{\@fontswitch\relax\mathcal G}$ is the permutation of tensor factors, and
\item the {\bf equivariance condition}
\begin{equation}
D^-_t{\@fontswitch\relax\mathcal R}=0\iff    (t\,\otimes \operatorname{id}){\@fontswitch\relax\mathcal R}^l = (\operatorname{id}\otimes\, t){\@fontswitch\relax\mathcal R}^r\in{\@fontswitch\relax\mathcal G}_0^{2\otimes}.\label{2ybequiv}
\end{equation}
\end{enumerate}
We call the tuple ${\@fontswitch\relax\mathcal R}$ invertible iff ${\@fontswitch\relax\mathcal R}^l,{\@fontswitch\relax\mathcal R}^r$ are both invertible.

\label{2yangbaxter}
     The 2-$R$-matrix of a quasitriangular 2-bialgebra $({\@fontswitch\relax\mathcal G},\cdot,\Delta,{\@fontswitch\relax\mathcal R})$ satisfies the \textbf{2-Yang-Baxter equations}
    \begin{align}
    {\@fontswitch\relax\mathcal R}^r_{23}({\@fontswitch\relax\mathcal R}^r_{13}\cdot_l{\@fontswitch\relax\mathcal R}_{12}^l) = ({\@fontswitch\relax\mathcal R}^l_{12}\cdot_r{\@fontswitch\relax\mathcal R}^r_{13}){\@fontswitch\relax\mathcal R}^r_{23},\qquad 
    ({\@fontswitch\relax\mathcal R}^l_{23}\cdot_l{\@fontswitch\relax\mathcal R}^r_{13}) {\@fontswitch\relax\mathcal R}^r_{12}= {\@fontswitch\relax\mathcal R}^r_{12} ({\@fontswitch\relax\mathcal R}^r_{13}\cdot_r{\@fontswitch\relax\mathcal R}^l_{23} )  ,    \nonumber\\
      {\@fontswitch\relax\mathcal R}^l_{23}({\@fontswitch\relax\mathcal R}^l_{13}\cdot_r{\@fontswitch\relax\mathcal R}_{12}^r) = ({\@fontswitch\relax\mathcal R}^r_{12}\cdot_l{\@fontswitch\relax\mathcal R}^l_{13}){\@fontswitch\relax\mathcal R}^l_{23},\qquad 
    ({\@fontswitch\relax\mathcal R}^r_{23}\cdot_r{\@fontswitch\relax\mathcal R}^l_{13}) {\@fontswitch\relax\mathcal R}^l_{12}= {\@fontswitch\relax\mathcal R}^l_{12} ({\@fontswitch\relax\mathcal R}^l_{13}\cdot_l{\@fontswitch\relax\mathcal R}^r_{23} )     .\label{2yangbax2}
\end{align}

\label{weak2alg}
A 2-term $A_\infty$-algebra, or equivaelntly a {\bf weak 2-algebra} $({\@fontswitch\relax\mathcal G},{\@fontswitch\relax\mathcal T})$, is a map $t:{\@fontswitch\relax\mathcal G}_{-1}\rightarrow {\@fontswitch\relax\mathcal G}_0$ between a pair of {\it not necessarily associative} algebras, together with an {invertible homotopy map} ${\@fontswitch\relax\mathcal T}:{\@fontswitch\relax\mathcal G}^{3\otimes}_0\rightarrow {\@fontswitch\relax\mathcal G}_{-1}$ such that we have the conditions  \eqref{algpeif1}, \eqref{algpeif2}, as well as
\begin{enumerate}
    \item the {\bf weak 1-associativity}, 
    \begin{equation}
        (xx')x'' - x(x'x'') = t{\@fontswitch\relax\mathcal T}(x,x',x''),\qquad (yy')y'' - y(y'y'') = {\@fontswitch\relax\mathcal T}(ty,ty',ty'')  \nonumber
    \end{equation}
    and the {\bf weak bimodularity},
    \begin{gather}
        x\cdot (x'\cdot y) - (xx')\cdot y = {\@fontswitch\relax\mathcal T}(x,x',ty)\qquad
        (x\cdot y)\cdot x' - x\cdot (y\cdot x') = {\@fontswitch\relax\mathcal T}(x,ty,x'),\nonumber\\
        (y\cdot x)\cdot x' - y\cdot (xx') = {\@fontswitch\relax\mathcal T}(ty,x,x'),
        \nonumber
    \end{gather}
    for each $x,x',x''\in{\@fontswitch\relax\mathcal G}_0$ and $y,y',y''\in{\@fontswitch\relax\mathcal G}_{-1}$,
    \item the {\bf Hochschild 3-cocycle condition},
    \begin{equation}
        x_1\cdot {\@fontswitch\relax\mathcal T}(x_2,x_3,x_4)+{\@fontswitch\relax\mathcal T}(x_1,x_2,x_3)\cdot x_4 = {\@fontswitch\relax\mathcal T}(x_1x_2,x_3,x_4)- {\@fontswitch\relax\mathcal T}(x_1,x_2x_3,x_4)+{\@fontswitch\relax\mathcal T}(x_1,x_2,x_3x_4)\nonumber
    \end{equation}
    for each $x_1,\dots,x_4\in{\@fontswitch\relax\mathcal G}_0$.
\end{enumerate}
We call $({\@fontswitch\relax\mathcal G},{\@fontswitch\relax\mathcal T})$ a unital weak 2-algebra if we have a unit map $\eta:k\rightarrow {\@fontswitch\relax\mathcal G}$

that satisfies the usual conditions \eqref{def:unity}, and such that ${\@fontswitch\relax\mathcal T}$ is {\bf normalized} --- namely it vanishes whenever any of its arguments are $0$ or $\eta_0$.

Let $\Delta_1:{\@fontswitch\relax\mathcal G}_0\rightarrow {\@fontswitch\relax\mathcal G}_{-1}^{3\otimes}$ denote an {\it invertible} trilinear map. Together with the maps $(\Delta_{-1},\Delta_0)$ defined as in  \eqref{grpdcoprod}, we say that the tuple $({\@fontswitch\relax\mathcal G},\Delta=(\Delta_{-1},\Delta_0,\Delta_1))$ is a {\bf weak 2-coalgebra} iff coequivariance  \eqref{cohgrpd+}, coPeiffer identity  \eqref{cohgrpd-}, \textbf{weak coassociativity} 
\begin{eqnarray}
    \Delta_{-1}\circ\Delta_{-1} &=& \Delta_1\circ t,\nonumber\\
    (\Delta_{-1} + \Delta_0)\circ\Delta_0 &=& D_t\circ\Delta_1,\label{weakcohgrpd1}
\end{eqnarray}
and \textbf{2-coassociativity}
\begin{equation}
    \Delta_1\circ\Delta_0 = \Delta_{-1}\circ\Delta_1 \label{weakcohgrpd2}
\end{equation}
are satisfied. In which case we call $\Delta_1$ the {\bf coassociator} of ${\@fontswitch\relax\mathcal G}$. 

We call $({\@fontswitch\relax\mathcal G},\Delta)$ \textbf{counital} if it is equipped with a counit $\epsilon:k\rightarrow{\@fontswitch\relax\mathcal G}$ satisfying the usual conditions, and $\epsilon\circ\Delta_1=0$.

\label{wk2bialg}
The tuple $({\@fontswitch\relax\mathcal G},{\@fontswitch\relax\mathcal T},\Delta)$ is a (unital) {\bf weak 2-bialgebra} iff $({\@fontswitch\relax\mathcal G},{\@fontswitch\relax\mathcal T})$ is a weak 2-algebra and $({\@fontswitch\relax\mathcal G},\Delta)$ is a (counital) weak 2-coalgebra. Equivalently, $({\@fontswitch\relax\mathcal G},{\@fontswitch\relax\mathcal T},\Delta)$ is a weak 2-bialgebra iff the tuple $\Delta=(\Delta_1,\Delta_0,\Delta_{-1})$ satisfies  \eqref{cohgrpd-}, \eqref{cohgrpd+}, \eqref{weakcohgrpd1}-\eqref{weakcohgrpd3}, \eqref{2algcoprod} and \eqref{coassocalg}.

A weak 2-bialgebra $({\@fontswitch\relax\mathcal G},{\@fontswitch\relax\mathcal T},\Delta)$ is called {\bf quasi-2-bialgebra} if ${\@fontswitch\relax\mathcal T}=0$.

Let $({\@fontswitch\relax\mathcal G}^*,{\@fontswitch\relax\mathcal T}^*,\Delta^*)$ be the dual weak 2-bialgebra. By a straightforward computation, it is obvious that the conditions  \eqref{cohgrpd+}, \eqref{cohgrpd-}, \eqref{weakcohgrpd1}, \eqref{weakcohgrpd3} on $({\@fontswitch\relax\mathcal G}^*,\Delta^*)$ hold iff the Peiffer conditions, weak 1-associativity and weak bimodularity hold for the 2-algebra ${\@fontswitch\relax\mathcal G}$. The fact that $(\Delta_{-1}^*,\Delta_0^*)$ are 2-algebra maps, as well as the units/counits, are treated the same way as in the proof of {\bf Proposition \ref{2bialg}}.

The two non-trivial identities to check are  \eqref{weakcohgrpd2}, \eqref{coassocalg}. We will use the Sweedler notation for $\Delta_1$, $\Delta_1 x= x_{(1)}\otimes x_{(2)}\otimes x_{(3)}$. Note $x\in{\@fontswitch\relax\mathcal G}_0$, but $x_{(i)}\in {\@fontswitch\relax\mathcal G}_{-1}$ for $i=1,2,3$.


We begin first with the latter, and check that $\Delta_1$ is a 2-algebra map. We have
\begin{equation}
    \langle \Delta_1^*(ff'),x\otimes x'\otimes x''\rangle = \langle ff',{\@fontswitch\relax\mathcal T}(x,x',x'')\rangle = \langle f\otimes f',\Delta_{-1}{\@fontswitch\relax\mathcal T}(x,x',x'')\rangle,\nonumber
\end{equation}
while (recall $\Delta_0'$ dualizes to the multiplication on ${\@fontswitch\relax\mathcal G}_0^*$, and $ f_{(i)}\in {\@fontswitch\relax\mathcal G}^*_{-1}$)
\begin{eqnarray}
    \langle  f_{(1)} f_{(1)}'\otimes f_{(2)} f_{(2)}'\otimes  f_{(3)} f_{(3)}', x\otimes x'\otimes x''\rangle &=& \langle \bigotimes_{i=1}^3 f_{(i)}\otimes  f_{(i)}',\Delta_0'(x)\otimes\Delta_0'(x')\otimes\Delta_0'(x'')\rangle \nonumber\\
    &=&\langle ( f_{(1)}\otimes  f_{(1)}')\otimes ( f_{(2)}\otimes f_{(2)}')\otimes ( f_{(3)}\otimes  f_{(3)}'), \nonumber\\
    &\qquad&\quad (\bar x_{(1)}\otimes \bar x_{(2)}) \otimes (\bar x'_{(1)}\otimes \bar x'_{(2)})\otimes (\bar x''_{(1)}\otimes \bar x''_{(2)})\rangle \nonumber\\
    &=& \langle \Delta_1^*(f) \otimes \Delta_1^*(f'), \nonumber\\
    &\qquad& \quad(\bar x_{(1)}\otimes \bar x_{(1)}'\otimes \bar x_{(1)}'')\otimes (\bar x_{(2)}\otimes \bar x_{(2)}'\otimes \bar x_{(2)}'')\rangle \nonumber\\
    &=& \langle f\otimes f',{\@fontswitch\relax\mathcal T}(\bar x_{(1)},\bar x_{(1)}',\bar x_{(1)}'')\otimes {\@fontswitch\relax\mathcal T}(\bar x_{(2)},\bar x_{(2)}',\bar x_{(2)}'')\rangle,\nonumber
\end{eqnarray}
meaning that $\Delta_1$ is a 2-algebra map on $({\@fontswitch\relax\mathcal G},{\@fontswitch\relax\mathcal T})$ iff $\Delta_1^*$ is also one on $({\@fontswitch\relax\mathcal G}^*,{\@fontswitch\relax\mathcal T}^*)$.

We now check  \eqref{weakcohgrpd3}. Fix arbitrary elements $f_1,\dots,f_4\in{\@fontswitch\relax\mathcal G}_{-1}^*$, we compute
\begin{eqnarray}
    \langle f_1\cdot{\@fontswitch\relax\mathcal T}^*(f_2,f_3,f_4),x\rangle &=& \langle f_1\otimes {\@fontswitch\relax\mathcal T}^*(f_2,f_3,f_4),\Delta_0^l(x)\rangle = \langle f_1\otimes\dots\otimes f_4,(1\otimes \Delta_1)\circ\Delta_0^l(x)\rangle,\nonumber\\
    \langle {\@fontswitch\relax\mathcal T}^*(f_1,f_2,f_3)\cdot f_4,x\rangle &=& \langle {\@fontswitch\relax\mathcal T}^*(f_1,f_2,f_3)\otimes f_4,\Delta_0^r(x)\rangle = \langle f_1\otimes\dots\otimes f_4,(\Delta_1\otimes 1)\circ\Delta_0^r(x)\rangle;\nonumber
\end{eqnarray}
on the other hand, we have 
\begin{eqnarray}
    \langle {\@fontswitch\relax\mathcal T}^*(f_1f_2,f_3,f_4),x\rangle &=& \langle f_1f_2\otimes f_3\otimes f_4,\Delta_1(x)\rangle = \langle f_1\otimes\dots\otimes f_4,(\Delta_{-1}\otimes 1\otimes 1)\circ\Delta_1(x)\rangle,\nonumber\\
    \langle {\@fontswitch\relax\mathcal T}^*(f_1,f_2,f_3f_4),x\rangle &=& \langle f_1\otimes f_2\otimes f_3 f_4,\Delta_1(x)\rangle = \langle f_1\otimes\dots\otimes f_4,(1\otimes 1\otimes \Delta_{-1})\circ\Delta_1(x)\rangle,\nonumber\\
    \langle {\@fontswitch\relax\mathcal T}^*(f_1,f_2f_3,f_4),x\rangle &=& \langle f_1\otimes f_2f_3\otimes f_4,\Delta_1(x)\rangle = \langle f_1\otimes\dots\otimes f_4,(1\otimes \Delta_{-1}\otimes 1)\circ\Delta_1(x)\rangle.\nonumber
\end{eqnarray}
By summing these up, the Hochschild 3-cocycle condition for ${\@fontswitch\relax\mathcal T}^*$ is equivalent to
\begin{equation}
    (1\otimes \Delta_1)\circ\Delta_0^l + (\Delta_1\otimes 1)\circ\Delta_0^r=\Delta_1\circ\Delta_0=\Delta_{-1}\circ\Delta_1.\nonumber
\end{equation}
which is exactly  \eqref{weakcohgrpd3}.

The fact that ${\@fontswitch\relax\mathcal K}$ factors into skeletal 2-subalgebras means that it must also be skeletal itself. This allows us to leverage the proof of {\bf Theorem \ref{2qd}} to reconstruct the underlying 2-bialgebra structure of ${\@fontswitch\relax\mathcal K}\cong D({\@fontswitch\relax\mathcal G})$ as a 2-quantum double. 

    The subtlety here is that we must now keep track of the 3-cocycle ${\@fontswitch\relax\mathcal T}_K: {\@fontswitch\relax\mathcal K}_0^{3\otimes}\rightarrow {\@fontswitch\relax\mathcal K}_{-1}$ in ${\@fontswitch\relax\mathcal K}$ when we, in particular, invoke associativity in the form
    \begin{eqnarray}
        {\@fontswitch\relax\mathcal T}_K(\iota_0(x),\iota_0(x'),\jmath_0(f))&\equiv& \rhd_1^{x,x'}(f) : (\iota_0(x)\hat\cdot\iota_0(x'))\hat\cdot\jmath_0(f)\xrightarrow{\sim} \iota_0(x)\hat\cdot(\iota_0(x')\hat\cdot\jmath_0(f)),\nonumber\\
        {\@fontswitch\relax\mathcal T}_K(\iota_0(x),\jmath_0(f),\jmath_0(f'))&\equiv& (x)\lhd_1^{f,f'} :(\iota_0(x)\hat\cdot\jmath_0(f))\hat\cdot \jmath_0(f')\xrightarrow{\sim} \iota_0(x)\hat\cdot(\jmath_0(f)\hat\cdot \jmath_0(f')).\nonumber
    \end{eqnarray}
    Now in the skeletal case, the braiding map $\Psi = (\Psi_0,\Psi_{-1};\bar\Psi): {\@fontswitch\relax\mathcal G}\otimes {\@fontswitch\relax\mathcal H}\rightarrow {\@fontswitch\relax\mathcal H}\otimes {\@fontswitch\relax\mathcal G}$ is still defined as in  \eqref{braid}. However, the components $\rhd_1,\lhd_1$ now give rise to associators
    \begin{eqnarray}
        \rhd_1&:&\Psi \circ(\hat\cdot \otimes \operatorname{id}) \xRightarrow{\sim} (\operatorname{id}\otimes \hat\cdot)\circ \Psi_{12}\circ \Psi_{23},\nonumber\\
        \lhd_1&:&\Psi\circ(\operatorname{id}\otimes \hat\cdot) \xRightarrow{\sim} (\hat\cdot\otimes \operatorname{id})\circ \Psi_{23}\circ \Psi_{12}\label{2yb2}
    \end{eqnarray}
    that implement the braiding relations  \eqref{2yb1}. These braiding associators satisfy a set of algebraic conditions following from the 3-cocycle condition  \eqref{2dd3cocyc} for ${\@fontswitch\relax\mathcal T}_K$.

    With the components $\rhd_1,\lhd_1$ as defined above, we now wish to reconstruct the Hochschild 3-cocycles ${\@fontswitch\relax\mathcal T}_G,{\@fontswitch\relax\mathcal T}_H$ of ${\@fontswitch\relax\mathcal G},{\@fontswitch\relax\mathcal H}$ from ${\@fontswitch\relax\mathcal T}_K$. Note this cannot be achieved by just restricting ${\@fontswitch\relax\mathcal T}_K$ via the span  \eqref{span}, as this does not have the desired codomains. For instance, the restriction ${\@fontswitch\relax\mathcal T}_K|_{\operatorname{im}\iota={\@fontswitch\relax\mathcal G}}: G_0^{3\otimes}\rightarrow {\@fontswitch\relax\mathcal K}_{-1} \cong {\@fontswitch\relax\mathcal G}_{-1}\otimes {\@fontswitch\relax\mathcal H}_{-1}$ in general lands in the tensor product, for which only the ${\@fontswitch\relax\mathcal G}_{-1}$-valued component gives the desired 3-cocycle ${\@fontswitch\relax\mathcal T}_G$ on ${\@fontswitch\relax\mathcal G}$. Nevertheless, with ${\@fontswitch\relax\mathcal T}_G,{\@fontswitch\relax\mathcal T}_H$ defined in this way, having the span  \eqref{span} means that the 3-cocycle condition for ${\@fontswitch\relax\mathcal T}_K$ implies $({\@fontswitch\relax\mathcal G},{\@fontswitch\relax\mathcal T}_G),({\@fontswitch\relax\mathcal H},{\@fontswitch\relax\mathcal T}_H)$ form a matched pair of weak 2-bialgebras, as in  \eqref{2dd3cocyc}. 

    The "undesirable" piece $\tilde{{\@fontswitch\relax\mathcal T}}_G$, namely the component of ${\@fontswitch\relax\mathcal T}_K|_{{\@fontswitch\relax\mathcal G}}$ valued in ${\@fontswitch\relax\mathcal H}_{-1}$, is a Hochschild coboundary. This follows from the definition of the inclusion $\iota=(\iota_{-1},\iota_0,\iota_1):{\@fontswitch\relax\mathcal G}\hookrightarrow {\@fontswitch\relax\mathcal K}$ as a weak homomorphism. Indeed, by projecting the last of  \eqref{weak2hom} for $\iota_1$ to ${\@fontswitch\relax\mathcal H}$, the first term $\iota_{-1}({\@fontswitch\relax\mathcal T}_{\@fontswitch\relax\mathcal G}(x,x',x''))|_{\@fontswitch\relax\mathcal H}=0$ vanishes whence
    \begin{eqnarray}
     \tilde{{\@fontswitch\relax\mathcal T}}_G&\equiv &{\@fontswitch\relax\mathcal T}_K(\iota_0(x),\iota_0(x'),\iota_0(x''))|_{\@fontswitch\relax\mathcal H} \nonumber\\
     &=&
        \iota_0(x)\, \hat\cdot\, \iota_1(x',x'')|_{\@fontswitch\relax\mathcal H} -~\iota_1(xx',x'')|_{\@fontswitch\relax\mathcal H}+\iota_1(x,x'x'')|_{\@fontswitch\relax\mathcal H} - \iota_1(x,x')|_{\@fontswitch\relax\mathcal H}\hat\cdot \iota_0(x'')\nonumber\\
        &=& d_{HH}[\iota_1|_{\@fontswitch\relax\mathcal H}](x,x',x''),\nonumber
    \end{eqnarray}
    where $d_{HH}$ is the Hochschild differential \cite{Wagemann+2021}.
    Similar arguments show that $\tilde{{\@fontswitch\relax\mathcal T}}_H=d_{HH}[\jmath_1|_{\@fontswitch\relax\mathcal G}]$ is a Hochschild coboundary as well. This establishes the weak equivalence ${\@fontswitch\relax\mathcal K}\sim D({\@fontswitch\relax\mathcal G})$.


    The same argument as above, but dualized, is applied to reconstruct $(\Delta_G)_1$ and $(\Delta_H)_1$ from the coassociator $(\Delta_K)_1$. The coassociator conditions  \eqref{weakcohgrpd1}-\eqref{weakcohgrpd3}, as well as  \eqref{coassocalg}, for them follow from those for $(\Delta_K)_1$.

\label{weakbimodule}
We say that $V$ is a \textbf{${\@fontswitch\relax\mathcal G}$-bimodule} if $({\@fontswitch\relax\mathcal G}\oplus V,\cdot) \in \text{2Alg}$ is             
a weak 2-algebra. In other words,
\begin{itemize}
    \item[(i)] $({\@fontswitch\relax\mathcal G}\oplus V)_{-1} \equiv {\@fontswitch\relax\mathcal G}_{-1}\oplus V_{-1}$ is a weak $({\@fontswitch\relax\mathcal G}\oplus V)_0:={\@fontswitch\relax\mathcal G}_0\oplus V_0$-bimodule, 
\item[(ii)] the map $t\oplus \partial:{\@fontswitch\relax\mathcal G}_{-1}\oplus V_{-1}\rightarrow {\@fontswitch\relax\mathcal G}_0\oplus V_0$ is equivariant with respect to $\cdot$ and satisfies the Peiffer identity\footnote{The Peiffer identity states $y\Yright w = (ty)\rhd w = y\Yright(\partial w)$, and similarly $w\Yleft y = (\partial w)\Yleft y= w\lhd(ty)$. If we write $y\Yright v = \Upsilon_y v$, then we reproduce precisely the 2-representation properties  \eqref{genpeif}.}, 
\item[(iii)] there exists a well-defined trilinear invertible map $({\@fontswitch\relax\mathcal G}_0\oplus V_0)^{3\otimes}\rightarrow {\@fontswitch\relax\mathcal G}_{-1}\oplus V_{-1}$ that satisfies the Hochschild 3-cocycle condition.
\end{itemize}

\label{weak2end}
We emphasize here that the 2-category $\mathsf{2Vect}^{BC}$ of Baez-Crans 2-vector spaces is completely strict \cite{Baez:2003fs}, and hence its algebra objects (ie. associative 2-algebras/algebra crossed-modules) and its endomorphism categories $\operatorname{End}(V) = \operatorname{End}_{\mathsf{2Vect}^{BC}}(V)$ do not carry homotopy data. Weak 2-algebras/2-term $A_\infty$-algebras are therefore not part of the theory of the usual Baez-Crans 2-vector spaces. Instead, they constitute algebra objects in the {homotopy refinement} $\mathsf{2Vect}^{hBC}$ of $\mathsf{2Vect}^{BC}$. The difference between the setting $\mathsf{2Vect}^{hBC}$ and the Kapranov-Voevodsky setting $\mathsf{2Vect}^{KV}$ is currently under investigation by one of the authors. In Appendix \ref{weak2repthy}, we shall establish properties of weak 2-representations
and relate it to those in the literature \cite{Delcamp:2021szr,Delcamp:2023kew,Douglas:2018,Baez:2012}.

\label{weak2rep}
A {\bf weak 2-representation} $(\varrho,\rho):{\@fontswitch\relax\mathcal G}\rightarrow \mathfrak{End}(V)$ of ${\@fontswitch\relax\mathcal G}$ on $V$ is a homomorphism between weak 2-algebras as in  \eqref{weak2hom}. In other words, $\rho=(\rho_0,\rho_1)$ is a chain map
\begin{equation}
    \begin{tikzcd}
{\@fontswitch\relax\mathcal G}_{-1} \arrow[d, "\rho_1"] \arrow[r, "t"]     & {\@fontswitch\relax\mathcal G}_0 \arrow[d, "\rho_0"]  \\
\mathfrak{End}(V)_{-1} \arrow[r, "\delta"] & \mathfrak{End}(V)_{0}
\end{tikzcd}\label{commsq}
\end{equation}
which preserves the 2-algebra structures {\it up to homotopy},
\begin{eqnarray}
    \delta\varrho(x,x') &=& \rho_0(xx') - \rho_0(x)\rho_0(x'),\nonumber\\
    \varrho(x,ty) &=& \rho_1(x\cdot y) - \rho_0(x)\cdot \rho_1(y),\nonumber\\
    \varrho(ty,x) &=& \rho_1(y\cdot x) - \rho_1(y)\cdot \rho_0(x),\label{weak2repalg}
\end{eqnarray}
and for which the Hochschild 3-cocycles ${\@fontswitch\relax\mathcal T},\mathfrak{T}$ of respectively ${\@fontswitch\relax\mathcal G}$ and $ \mathfrak{End}(V)$  satisfy the following compatibility conditions
\begin{eqnarray}
    \rho_1({\@fontswitch\relax\mathcal T}(x,x',x'')) &=& \rho_0(x)\cdot \varrho(x',x'')- \varrho(xx',x'') \nonumber\\
     &\qquad&+~ \varrho(x,x'x'') - \varrho(x,x')\cdot \rho_0(x'')\nonumber\\
     &\qquad& +~\mathfrak{T}(\rho_0(x),\rho_0(x'),\rho_0(x'')),\label{weak2rephom}
\end{eqnarray}
where $x,x',x''\in{\@fontswitch\relax\mathcal G}_0$ and $y\in{\@fontswitch\relax\mathcal G}_{-1}$. We require $\varrho$ to be invertible.

We call $\rho$ a {\bf strict 2-representation}  if $\varrho=0$ identically.

\label{weak2int}
A {\bf weak 2-intertwiner} $i = (I,i_1,i_0):V\rightarrow W$ consist of a 2-vector space homomorphism $(i_1,i_0): V\rightarrow W$ together with a collection of invertible cochain homotopies $I_{x,i}: V_0\rightarrow W_{-1}$ satisfying 
\begin{equation}
    \partial I_{x,i} = i_0\circ \rho_0^0(x) - \rho'^0_0(x)\circ i_0 ,\qquad I_{x,i}\partial = i_1\circ \rho_0^1(x) - \rho'^1_0(x)\circ i_1\nonumber
\end{equation}
for each $x\in {\@fontswitch\relax\mathcal G}_0$, as well as 
\begin{equation}
    I_{ty,i} = i_1\circ\rho_1(y) - \rho_1'(y)\circ i_0\nonumber
\end{equation}
for each $y\in {\@fontswitch\relax\mathcal G}_{-1}$. Moreover, $I_{\bullet,i}$ trivializes $\varrho-\varrho'$ as a Hochschild 2-cocycle, in the sense that for each $x,x'\in {\@fontswitch\relax\mathcal G}_0$,
\begin{equation}
     \operatorname{id}_i\otimes\varrho(x,x') - \varrho'(x,x')\otimes \operatorname{id}_i = \operatorname{id}_{\rho_0(x)}\otimes I_{x',i} - I_{xx',i}+  I_{x,i} \otimes\operatorname{id}_{\rho_0(x')},\label{2inthomotopy}
\end{equation}
where $\operatorname{id}_i:i\Rightarrow i$ denotes the identity cochain homotopy on the intertwiner $i$.

\label{weakmodif}
A {\bf modification} $\mu:i\Rightarrow i'$ between two weak 2-intertwiners is a ${\@fontswitch\relax\mathcal G}$-equivariant cochain homotopy
\begin{equation}
    \begin{tikzcd}
V_{-1} \arrow[r, "\partial"] \arrow[d, "i_1-i_1'"'] & V_0 \arrow[ld, "\mu"'] \arrow[d, "i_0-i_0'"] \\
W_{-1} \arrow[r, "\partial'"]                      & W_0                                        
\end{tikzcd},\label{modif}
\end{equation}
where $\mu$ intertwines between $\rho_1(y),\rho_1'(y)$ for each $y\in {\@fontswitch\relax\mathcal G}_{-1}$, as cochain homotopies. Moreover, $\mu$ trivializes $I_{\cdot,i}-I_{\cdot,i'}$ as a Hochschild 1-cocycle, in the sense that
\begin{equation}
    I_{x,i} - I_{x,i'} = \operatorname{id}_{\rho_0(x)}\otimes \mu-\mu   \label{modifhomotopy}
\end{equation}
for all $x\in {\@fontswitch\relax\mathcal G}_0$, as a relation between cochain homotopies.

\label{monoidal2rep2cat}
Let $i:V\rightarrow U$ denote a 2-intertwiner. We have the following diagrams
\begin{equation}
\begin{tikzcd}
V\otimes W \arrow[rr, "\rho_{V\otimes W}"] \arrow[dd, "i"'] &                                   & V\otimes W \arrow[dd, "i"] \\
                                                            & \xRightarrow{\rho_{i\otimes W}} &                            \\
U\otimes W \arrow[rr, "\rho_{U\otimes W}"]                  &                                   & U\otimes W
\end{tikzcd},\qquad \begin{tikzcd}
W\otimes V \arrow[rr, "\rho_{W\otimes V}"] \arrow[dd, "i"'] &                                   & W\otimes V \arrow[dd, "i"] \\
                                                            & \xRightarrow{\rho_{W\otimes i}} &                            \\
W\otimes U \arrow[rr, "\rho_{W\otimes U}"]                  &                                   & W\otimes U                
\end{tikzcd} \nonumber
\end{equation}
in $\operatorname{2Rep}^{\@fontswitch\relax\mathcal T}({\@fontswitch\relax\mathcal G})$.

Let us focus first on the left diagram. The goal is to show that $\rho_{i\otimes W}$ defines a cochain homotopy which fits into the following diagram
\begin{equation}
    \begin{tikzcd}
V_{-1}\otimes W_{-1} \arrow[rr, "D^+"] \arrow[d] &  & V_{-1}\otimes W_0\oplus V_0\otimes W_{-1} \arrow[d] \arrow[rr, "D^-"] \arrow[lld, "\rho_{i\otimes W}"'] &  & V_0\otimes W_0 \arrow[d] \arrow[lld, "\rho_{i\otimes W}"'] \\
U_{-1}\otimes W_{-1} \arrow[rr, "D^+"']          &  & U_{-1}\otimes W_0\oplus U_0\otimes W_{-1} \arrow[rr, "D^-"']                                         &  & U_0\otimes W_0                                         
\end{tikzcd},\nonumber
\end{equation}
where the horizontal maps are the differentials given in  \eqref{grtensor}, and the vertical maps are various components of $\rho_{V\otimes W}\circ i - i\circ\rho_{V\otimes W}$. 

The key is the commutation relation  \eqref{commsq}, which allows us to write
\begin{equation}
    \delta(\rho_1(y)) = (\rho_1(y)\partial,\partial \rho_1(y)) = (\rho_0^1(ty),\rho_0^0(ty)) \nonumber
\end{equation}
for each $y\in{\@fontswitch\relax\mathcal G}_{-1}$, as well as the definition  \eqref{deg0sweed} of $\Delta_0'$. Directly computing, we have for the rightmost triangle
\begin{eqnarray}
    D^-\rho_{i\otimes W} &=& \partial_U(\rho_U)_1(x_{(1)}^l) \circ i \otimes (\rho_W)_0^0(x_{(2)}^l) - (-1)^\text{deg} i\circ (\rho_V)_0(x_{(1)}^r) \otimes \partial_W(\rho_W)_0^0(x_{(2)}^r)\nonumber\\
    &=& (\rho_U)_0^0(tx_{(1)}^l) \circ i\otimes (\rho_W)_0^0(x_{(2)}^l) - i\circ (\rho_V)_0^0(x_{(1)}^r)\otimes (\rho_W)_0^0(tx_{(2)}^r) \nonumber\\
    &=& \rho_{U\otimes W} \circ i - i\circ\rho_{V\otimes W}\nonumber
\end{eqnarray}
as maps on $V_0\otimes W_0$ (with deg = 0), and similarly we have for the leftmost triangle
\begin{eqnarray}
    \rho_{i\otimes W}D^+ &=& (\rho_U)_1(x_{(1)}^l)\partial_U \circ i \otimes (\rho_W)_0^1(x_{(2)}^l) + (-1)^\text{deg} i\circ (\rho_V)_0(x_{(1)}^r) \otimes (\rho_W)_0^0(x_{(2)}^r)\partial_W\nonumber\\
    &=& (\rho_U)_0^1(tx_{(1)}^l) \circ i\otimes (\rho_W)_0^1(x_{(2)}^l) - i\circ (\rho_V)_0^1(x_{(1)}^r)\otimes (\rho_W)_0^1(tx_{(2)}^r) \nonumber\\
    &=& \rho_{U\otimes W} \circ i - i\circ\rho_{V\otimes W}\nonumber
\end{eqnarray}
as maps on $V_{-1}\otimes W_{-1}$ (with deg = -1). 

Now consider the middle section. We need to compute
\begin{gather}
    D^+\rho_{i\otimes W} = (\rho_U)_0^1(tx_{(1)}^l) \circ i\otimes (\rho_W)_0^0(x_{(2)}^l) - i\circ (\rho_V)_0^0(x_{(1)}^r)\otimes (\rho_W)_0^1(tx_{(2)}^r),\nonumber\\
    \rho_{i\otimes W}D^- = (\rho_U)_0^0(tx_{(1)}^l) \circ i\otimes (\rho_W)_0^1(x_{(2)}^l) - i\circ (\rho_V)_0^1(x_{(1)}^r)\otimes (\rho_W)_0^0(tx_{(2)}^r), \nonumber
\end{gather}
and sum them to find
\begin{eqnarray}
    D^+\rho_{i\otimes W}+ \rho_{i\otimes W}D^- &=& \left[(\rho_U)_0^1(tx_{(1)}^l)\otimes (\rho_W)_0^0(x_{(2)}^l) + (\rho_U)_0^0(tx_{(1)}^l)\otimes (\rho_W)_0^1(x_{(2)}^l)\right]\circ i \nonumber\\
    &\qquad& -~ i\circ \left[(\rho_V)_0^0(x_{(1)}^r)\otimes (\rho_W)_0^1(tx_{(2)}^r) + (\rho_V)_0^1(x_{(1)}^r)\otimes (\rho_W)_0^0(tx_{(2)}^r)\right] \nonumber\\
    &=& \rho_{U\otimes W} \circ i - i\circ\rho_{V\otimes W} \nonumber
\end{eqnarray}
as maps on $V_{-1}\otimes W_0\oplus V_0\otimes W_{-1}$. The other diagram is treated identically.

Consider first  \eqref{fusionassoc1}. We {\it precompose}  \eqref{weakcohgrpd3} with $t$ and reconstruct the associators corresponding to each term according to the definition,
\begin{gather}
    (\operatorname{id}\otimes (\Delta_1\circ t))\circ\Delta_{-1}\leadsto \operatorname{id}_i \otimes a_{jkl},\qquad ((\Delta_1\circ t)\otimes\operatorname{id} )\circ\Delta_{-1}\leadsto a_{ijk}\otimes\operatorname{id}_l,\nonumber\\
    (1\otimes \Delta_{-1}\otimes 1)\circ\Delta_1\circ t \leadsto a_{i(jk)l},\qquad
    -(\Delta_{-1}\otimes 1\otimes 1)\circ\Delta_1\circ t\leadsto a^\dagger_{(ij)kl},\nonumber\\
    -(1\otimes 1\otimes \Delta_{-1})\circ\Delta_1\circ t\leadsto a^\dagger_{ij(kl)},\nonumber
\end{gather}
where $\operatorname{id}_i:i\Rightarrow i$ denotes the identity modification on the 2-intertwiner $i$. Now note that, by coequivariance  \eqref{cohgrpd+} $D_t\circ \Delta_{-1} = \Delta_0\circ t$, we have
\begin{equation}
    (\operatorname{id}\otimes (\Delta_1\circ t))\circ\Delta_{-1} = (\operatorname{id}\otimes \Delta_1)\circ \Delta_0^l\circ t,\qquad  ( (\Delta_1\circ t)\otimes\operatorname{id})\circ\Delta_{-1} = (\Delta_1\otimes \operatorname{id})\circ \Delta_0^r\circ t,\nonumber
\end{equation}
whence the pentagon relation
\begin{equation}
    \begin{tikzcd}
                                                        &                                                             & ((ij) k) l \arrow[rrd, "a_{ijk}\operatorname{id}_l "]  &                  &                                                        \\
(ij) (kl) \arrow[rru, "a^\dagger_{(ij)kl}"] &                                                             &                                                                                            &                  & (i (jk)) l \arrow[ldd, "{a_{i(jk)l}}"] \\
                                                        &                                                             &                                                                                            &                  &                                                        \\
                                                        & i (j(kl)) \arrow[luu,"a^\dagger_{ij(kl)}"'] &                                                                                            & i ((jk) l) \arrow[ll,"\operatorname{id}_ia_{jkl}"'] &                                                       
\end{tikzcd}\label{2ddpentagon}
\end{equation}
is equivalently expressed as 
\begin{eqnarray}
    0&=&(1\otimes \Delta_{-1}\otimes 1)\circ\Delta_1 \circ t- (\Delta_{-1}\otimes 1\otimes 1)\circ\Delta_1\circ t - (1\otimes 1\otimes\Delta_{-1})\circ\Delta_1\circ t\nonumber\\
    &\qquad&~+(\Delta_1\otimes 1)\circ\Delta_0^r\circ t + (1\otimes \Delta_1)\circ\Delta_0^l\circ t\nonumber\\
    &=& \left[-\Delta_{-1}\circ\Delta_1 + \Delta_1\circ\Delta_0\right] \circ t,\nonumber
\end{eqnarray}
which is nothing but the 2-coassociativity  \eqref{weakcohgrpd3} precomposed with $t$. Now by the coPeiffer identity $\Delta_0' = D_t\Delta_0$  \eqref{deg0sweed}, the same argument shows that the pentagon relations for the rest of the associator 2-morphisms  \eqref{fusionassoc2}, \eqref{fusionassoc3} are equivalent to applying the $t$-map $D_t,D_t[2]$ to  \eqref{weakcohgrpd3}.

Similarly, under the complete $t$-map $D_t[3] = t\otimes t\otimes t$, the 2-coasscociativity condition  \eqref{weakcohgrpd3} becomes
\begin{equation}
    \Delta_0'\circ \Phi = \Phi\circ \Delta_0',\label{2coassobj}
\end{equation}
which by  \eqref{tensor2rep1} implies the pentagon relation for the associator 1-morphism  \eqref{fusionassoc4}.

The associator 2-morphism  \eqref{fusionassoc3} fits into diagrams of the form
\begin{equation}
\begin{tikzcd}
(VW)U \arrow[rr, "a_{VWU}"] \arrow[dd, "k"'] &                                   & V(WU) \arrow[dd, "k"] \\
                                                            & \xRightarrow{a_{VWk}} &                            \\
(VW)U' \arrow[rr, "a_{VWU'}"]                  &                                   & V(WU')                
\end{tikzcd}\label{assoc2morph}
\end{equation}
together with the associator morphism  \eqref{fusionassoc4}. Moreover, the associator 2-morphisms  \eqref{fusionassoc1}, \eqref{fusionassoc2} are completely determined by  \eqref{fusionassoc3}, \eqref{fusionassoc4}.

The first statement follows directly from the definitions, and by using the same argument as in the proofs of {\bf Lemma \ref{monoidal2rep2cat}}, and also later in {\bf Lemma \ref{braiding2rep2cat2}}. Similarly, by adapting the proof of {\bf Lemma \ref{2repdecomp}}, we see that  \eqref{fusionassoc1}, \eqref{fusionassoc2} admit the following decompositions
\begin{equation}
    a_{ijk} = (a_{V'W'k}\cdot a_{ijU})\circ t = \dots \text{etc.},\qquad D_\delta a_{ijU} = a_{V'jU}\cdot a_{iWU} = \dots \text{etc.},\nonumber
\end{equation}
where $D_\delta$ is the tensor triple of the $t$-map $\delta$ on $\mathfrak{End}(V)$, and "etc." means permutations of the subscripts. This proves the second statement.

\label{quasihopf}
Suppose the endomorphism $\Phi$ in  \eqref{fusionassoc4} is {\it inner}, in the sense that it is given by conjugation with an element --- also denoted $\Phi$ --- of ${\@fontswitch\relax\mathcal G}_0^{3\otimes}$, then the coassociativity condition becomes
\begin{equation}
    (\operatorname{id}\otimes\Delta_0')\circ\Delta'_0 = \Phi((\Delta_0'\otimes\operatorname{id})\circ\Delta_0')\Phi^{-1},\nonumber
\end{equation}
and the 2-coassociativity condition  \eqref{2coassobj} becomes
\begin{equation}
    ((\operatorname{id}\otimes\operatorname{id}\otimes\Delta_0')\Phi)((\Delta_0'\otimes\operatorname{id}\otimes\operatorname{id})\Phi) = (\Phi\otimes \eta_0)((\operatorname{id}\otimes\Delta_0'\otimes\operatorname{id})\Phi)(\eta_0\otimes\Phi),\nonumber
\end{equation}
where $\eta_0$ is the unit of ${\@fontswitch\relax\mathcal G}_0$. In other words, $({\@fontswitch\relax\mathcal G}_0,\Delta'_0,\Phi)$ in fact forms a {\it quasi-bialgebra} \cite{book-quasihopf}.

We shall {\bf define} the braiding maps $b_{ij}$ between two 1-morphisms $i,j$ by the decomposition formula
\begin{equation}
    \phi_{i,j} = b_{ij} = b_{jU}\cdot b_{Wi} = b_{Ti}\cdot b_{jV} ,\qquad \begin{cases} i: V\rightarrow U \\ j: W\rightarrow T\end{cases},\label{1morphbraid}
\end{equation}
and impose the condition that it be equal to the interchanger $\phi_{i,j}$ \eqref{interchange}. This bypasses the need for a $R$-matrix defined in degree-(-1), which is not encoded by the 2-$R$-matrix ${\@fontswitch\relax\mathcal R}$ anyway.

Note for each 2-representation $\rho$, the flip map $\text{flip}:V\otimes W\rightarrow W\otimes V$ is a 2-intertwiner between $\rho$ and $\rho'=\rho\circ\sigma$. Moreover, we interpret the cochain homotopy defined by $(\rho_{V\otimes W})_0^1(x)$ for each $x\in {\@fontswitch\relax\mathcal G}_0$ as a modification between the action $(\rho_{V\otimes W})_0^0(x)$ and itself, treated as a 2-intertwiner; similarly for $\rho'$. Therefore, in order for the mixed braiding map $b_{iW}$ to be a modification in $\operatorname{2Rep}({\@fontswitch\relax\mathcal G})$, it must commute with the cochain homotopy $(\rho_{V\otimes W})_0^1(x)$ --- namely
    \begin{equation}
        b_{iW}\ast (\rho_{V\otimes W})_0^1(x) = (\rho'_{W\otimes V})_0^1(x)\ast b_{iW},\nonumber
    \end{equation}
    where $\ast$ denotes the composition of cochain homotopies. With $\rho_{W\otimes V}' = (\rho_W\otimes\rho_V) \circ \sigma\circ \Delta$, this is satisfied by definition  \eqref{2repbraid1} of $b_{iW}$ iff
    \begin{equation}
        {\@fontswitch\relax\mathcal R}^r\Delta_0^r(x)=\sigma(\Delta_0^l(x)){\@fontswitch\relax\mathcal R}^r,\qquad  {\@fontswitch\relax\mathcal R}^l\Delta_0^l=\sigma(\Delta_0^r(x)){\@fontswitch\relax\mathcal R}^l,\label{2rmatint2}
    \end{equation}
    which is precisely  \eqref{def2R2}.

    Similarly, in order for the braiding map $b_{VW}$ to be a 2-intertwiner, it must commute with the action $(\rho_{V\otimes W})_0^0(x)$ for each $x\in {\@fontswitch\relax\mathcal G}_0$:
    \begin{equation}
        b_{VW} \circ (\rho_{V\otimes W})_0^0(x) = (\rho'_{W\otimes V})_0^0(x)\circ b_{VW},\nonumber
    \end{equation}
    where $\circ$ denotes the composition of 2-intertwiners. 


    First if the 2-representation $\rho$ were strict, then this translates to the algebraic condition
    \begin{equation}
        \sigma\Delta_0'(x)R = R\Delta_0'(x), \nonumber
    \end{equation}
    which in fact follows also from  \eqref{def2R2}. To see this, we recall the definitions  \eqref{deg0rmat} of $R$ and  \eqref{deg0sweed} of the coproduct $\Delta_0'$, and simply apply $t\otimes 1$ and $1\otimes t$ respectively to  \eqref{def2R2}. The fact that $t$ is an algebra homomorphism and that $(t\otimes 1)\circ\sigma = \sigma\circ(1\otimes t)$ proves the statement.


    Second, if the 2-representation $\rho$ were weak, then in general the component $\varrho$ gives rise to a possibly non-trivial invertible natural 2-morphism 
    \begin{equation}
        \varrho(\sigma\Delta'_0(x),R) - \varrho(R,\Delta_0'(x)).\nonumber
    \end{equation}
    We will not need this 2-morphism in the following so we shall suppose $I_{b_{VW},\bullet}=\operatorname{id}$.

\label{braiding2rep2cat2} Consider the intertwiners $i:V\rightarrow U$ and $j:U\rightarrow T$. 
The mixed braiding maps $b_{iW},b_{Wi}$ fit into the following diagrams
\begin{equation}
    \begin{tikzcd}
V\otimes W \arrow[rrr, "b_{VW}"] \arrow[dd, "i"'] &                                    &    & W\otimes V \arrow[dd, "i"] \\
                                                  & {} \arrow[r, "b_{iW}", Rightarrow] & {} &                            \\
U\otimes W \arrow[rrr, "b_{UW}"]                  &                                    &    & W\otimes U                
\end{tikzcd},\qquad     
\begin{tikzcd}
W\otimes V \arrow[rrr, "b_{WV}"] \arrow[dd, "i"'] &                                    &    & V\otimes W \arrow[dd, "i"] \\
                                                  & {} \arrow[r, "b_{Wi}", Rightarrow] & {} &                            \\
W\otimes U \arrow[rrr, "b_{WU}"]                  &                                    &    & U\otimes W                
\end{tikzcd}\nonumber
\end{equation}
in $\operatorname{2Rep}^{\@fontswitch\relax\mathcal T}({\@fontswitch\relax\mathcal G})$. Moreover, given a 2-intertwiner $j:U\rightarrow T$ composable with $i$, the corresponding braiding 2-morphisms compose as $b_{jW}\ast b_{iW} = b_{j\circ i,W}$.
\begin{equation}
    \begin{tikzcd}
V\otimes W \arrow[rrr, "b_{VW}"] \arrow[dd, "i"'] &                                    &    & W\otimes V \arrow[dd, "i"] \\
                                                  & {} \arrow[r, "b_{iW}", Rightarrow] & {} &                            \\
U\otimes W \arrow[rrr, "b_{UW}"]    \arrow[dd, "j"']               &                                    &    & W\otimes U  \arrow[dd, "j"']             
\\& {} \arrow[r, "b_{jW}", Rightarrow] & {} & \\ 
T\otimes W \arrow[rrr, "b_{WT}"]& & & W\otimes T 
\end{tikzcd}
=     
\begin{tikzcd}
V\otimes W \arrow[rrr, "b_{VW}"] \arrow[dd, "j\circ i"'] &                                    &    & W\otimes V \arrow[dd, "j\circ i"] \\
                                                  & {} \arrow[r, "b_{(j\circ  i)W}", Rightarrow] & {} &                            \\
T\otimes W \arrow[rrr, "b_{TW}"]                  &                                    &    & W\otimes T       
\end{tikzcd}\nonumber
\end{equation}

For brevity, we shall suppress the subscripts $V,U,W$ on the 2-representations. Recall the two equivalent ways $R^r,R^l$ to express $R$ in  \eqref{deg0rmat}. We can then write $$b_{UW} \circ i = \text{flip}\circ \rho_0(R^r) \circ i,\qquad i\circ b_{VW} = i\circ \text{flip}\circ \rho_0(R^l).$$ 

Consider the left diagram. As 2-morphisms in $\operatorname{2Rep}({\@fontswitch\relax\mathcal G})$ are given by cochain homotopies, we need to show that the definition  \eqref{2repbraid2} of the mixed braiding map $b_{iW} = b_{iW}^1 + b_{iW}^2$ fits into the following diagram 
\begin{equation}
    \begin{tikzcd}
V_{-1}\otimes W_{-1} \arrow[r, "D^+"] \arrow[d] & V_{-1}\otimes W_0 \oplus V_0\otimes W_{-1} \arrow[d] \arrow[r, "D^-"] \arrow[ld, "b_{iW}^2"'] & V_0\otimes W_0 \arrow[d] \arrow[ld, "b_{iW}^1"] \\
W_{-1}\otimes U_{-1} \arrow[r, "D^+"']          & W_{-1}\otimes U_0 \oplus W_0\otimes U_{-1} \arrow[r, "D^-"']                                 & W_0\otimes U_0                                 
\end{tikzcd},\label{mixedbraidhomotopy}
\end{equation}
where the vertical arrows are the various graded components of $b_{UW}\circ i - i\circ b_{VW}$, and the horizontal arrows are the differentials on the three-term tensor product complex  \eqref{grtensor}; for instance, the ones at the top row are given by $D^\pm= 1\otimes\partial_W\pm \partial_V\otimes 1$.

As in {\bf Lemma \ref{monoidal2rep2cat}}, the key towards this is the commutative square  \eqref{commsq}, which states that for each $y\in {\@fontswitch\relax\mathcal G}_{-1}$ we have
\begin{equation}
    (\rho_1(y)\partial,\partial\rho_1(y)) =  \delta(\rho_1)(y) = (\rho_0)(Ty) = (\rho_0^1(Ty),\rho_0^0(Ty)).\nonumber
\end{equation}
Let us examine first the commutative triangle on the ends of  \eqref{mixedbraidhomotopy}. First, for the right-most triangle, we compute in terms of the components $b_{iW}^{1,2}$ that
\begin{eqnarray}
    D^-b_{iW}^1 &=& (1\otimes\partial_V-\partial_W\otimes 1) \circ \text{flip} \circ \rho({\@fontswitch\relax\mathcal R})\nonumber\\
    &=& \text{flip}\circ \left[\rho_0^0({\@fontswitch\relax\mathcal R}^r_{(1)})\otimes \partial_W (\rho_1({\@fontswitch\relax\mathcal R}^r_{(2)}))\circ i-i\circ i\partial_V(\rho_1({\@fontswitch\relax\mathcal R}^l_{(1)}))\otimes \rho_0^0({\@fontswitch\relax\mathcal R}^l_{(2)})\right] \nonumber\\
    &=& \text{flip}\circ \left[\rho_0^0({\@fontswitch\relax\mathcal R}^r_{(1)}\otimes t{\@fontswitch\relax\mathcal R}_{(2)}^r)\circ  i+i\circ \rho_0^0(-t{\@fontswitch\relax\mathcal R}^l_{(1)} \otimes {\@fontswitch\relax\mathcal R}^l_{(2)})\right] \nonumber\\
    &=& b_{UW} \circ i - i \circ b_{VW}\nonumber
\end{eqnarray}
as maps on $V_0\otimes W_0$. Similarly for the left-most triangle, we have
\begin{eqnarray}
    b_{iW}^2D^+ &=& \text{flip} \circ \rho({\@fontswitch\relax\mathcal R})\circ ( 1\otimes\partial_W+\partial_V\otimes 1) \nonumber\\
    &=& \text{flip}\circ \left[\rho_0^1({\@fontswitch\relax\mathcal R}^r_{(1)})\otimes (\rho_1({\@fontswitch\relax\mathcal R}^r_{(2)}))\partial_W\circ i-i\circ (\rho_1({\@fontswitch\relax\mathcal R}^l_{(1)}))\partial_V\otimes \rho_0^1({\@fontswitch\relax\mathcal R}^l_{(2)})\right] \nonumber\\
    &=& \text{flip}\circ \left[\rho_0^1({\@fontswitch\relax\mathcal R}^r_{(1)}\otimes t{\@fontswitch\relax\mathcal R}_{(2)}^r)\circ i-i\circ \rho_0^1(t{\@fontswitch\relax\mathcal R}^l_{(1)} \otimes {\@fontswitch\relax\mathcal R}^l_{(2)})\right] \nonumber\\
    &=& b_{UW} \circ i - i \circ b_{VW}\nonumber
\end{eqnarray}
as maps $V_{-1}\otimes W_{-1}$. Note the sign $(-1)^\text{deg}$ in  \eqref{2repbraid2} is non-trivial here as ${\@fontswitch\relax\mathcal R}$ acts on the degree-(-1) part of the tensor product $V\otimes W$.

We now turn to the middle section of  \eqref{mixedbraidhomotopy}. We are required to compute the following,
\begin{eqnarray}
    D^+b_{iW}^2 &=& (1\otimes\partial_V+\partial_W\otimes 1 )\circ\text{flip}\circ \rho({\@fontswitch\relax\mathcal R})\nonumber\\
    &=& \text{flip}\circ \left[\rho_0^1({\@fontswitch\relax\mathcal R}_{(1)}^r)\otimes \partial_W(\rho_1({\@fontswitch\relax\mathcal R}_{(2)}^r))\circ i-i\circ \partial_V(\rho_1({\@fontswitch\relax\mathcal R}^l_{(1)}))\otimes \rho_0^1({\@fontswitch\relax\mathcal R}_{(2)}^l) \right] \nonumber\\
    &=& \text{flip}\circ \left[ \rho_0^1({\@fontswitch\relax\mathcal R}_{(1)}^r)\otimes \rho_0^0(t{\@fontswitch\relax\mathcal R}_{(2)}^r)\circ i-i\circ\rho_0^0(t{\@fontswitch\relax\mathcal R}^l_{(1)}) \otimes \rho_0^1({\@fontswitch\relax\mathcal R}_{(2)}^l)\right],\nonumber\\
    b_{iW}^1D^- &=& \text{flip}\circ \rho({\@fontswitch\relax\mathcal R}) \circ (1\otimes \partial_W-\partial_V\otimes 1 ) \nonumber\\
    &=& \text{flip} \circ \left[\rho_0^0({\@fontswitch\relax\mathcal R}^r_{(1)}) \otimes \rho_1({\@fontswitch\relax\mathcal R}_{(2)}^r)\partial_W\circ i -i\circ \rho_1({\@fontswitch\relax\mathcal R}_{(1)}^l)\partial_V\otimes \rho_0^0({\@fontswitch\relax\mathcal R}^l_{(2)})\right]\nonumber\\
    &=& \text{flip} \circ\left[\rho_0^0({\@fontswitch\relax\mathcal R}^r_{(1)}) \otimes \rho_0^1(t{\@fontswitch\relax\mathcal R}_{(2)}^r)\circ i -i\circ \rho_0^1(t{\@fontswitch\relax\mathcal R}_{(1)}^)\otimes \rho_0^0({\@fontswitch\relax\mathcal R}^l_{(2)})\right].\nonumber
\end{eqnarray}
Summing these and rearranging terms gives, as maps on $V_{-1}\otimes W_0\oplus V_0\otimes W_{-1}$,
\begin{gather}
    \text{flip}\circ \left[\rho_0^0({\@fontswitch\relax\mathcal R}^r_{(1)}) \otimes \rho_0^1(t{\@fontswitch\relax\mathcal R}_{(2)}^r) + \rho_0^1({\@fontswitch\relax\mathcal R}_{(1)}^r)\otimes \rho_0^0(t{\@fontswitch\relax\mathcal R}_{(2)}^r)\right]\circ i \\ 
    \qquad -~\text{flip}\circ i\circ \left[ \rho_0^1(t{\@fontswitch\relax\mathcal R}_{(1)}^l)\otimes \rho_0^0({\@fontswitch\relax\mathcal R}^l_{(2)})+\rho_0^0(t{\@fontswitch\relax\mathcal R}^l_{(1)}) \otimes \rho_0^1({\@fontswitch\relax\mathcal R}_{(2)}^l)\right] \nonumber\\
    = b_{UW}\circ i - i\circ b_{VW}. \nonumber
\end{gather}
The diagram on the right is treated identically, and this establishes the first statement. The second statement directly follows from the fact that $(j\circ i)\circ \rho_V = j\circ \rho_U \circ i = \rho_X\circ (j\circ i)$ for composable 2-intertwiners $i,j$.

A \textbf{2-$R$-matrix} ${\@fontswitch\relax\mathcal R}$ for a \textit{weak} 2-bialgebra $({\@fontswitch\relax\mathcal G},\Delta,\Delta_1)$ is defined as in \textbf{Definition \ref{2Rdef}}, except that \eqref{def2R1} is modified by the {\it dual} of ${\@fontswitch\relax\mathcal T}$ --- ie. the coassociator $\Delta_1$ --- namely, we have
\begin{gather}
    D_t\Delta_1(x)_{231}\cdot( 1\otimes\Delta_0){\@fontswitch\relax\mathcal R} \cdot D_t\Delta_1(x)_{123} = {\@fontswitch\relax\mathcal R}_{13}\cdot D_t\Delta_1(x)_{213}\cdot {\@fontswitch\relax\mathcal R}_{12},\nonumber\\
    D_t\Delta_1(x)_{312}^{-1}\cdot (\Delta_0\otimes 1){\@fontswitch\relax\mathcal R}\cdot D_t\Delta_1(x)_{213}^{-1} = {\@fontswitch\relax\mathcal R}_{13}\cdot D_t\Delta_1(x)_{132}^{-1}\cdot {\@fontswitch\relax\mathcal R}_{23},\label{quasi2rmatrix}
\end{gather}
for each $x\in {\@fontswitch\relax\mathcal G}_0$.

\label{braiddecomp}
For each $X\in\operatorname{2Rep}^{\@fontswitch\relax\mathcal T}({\@fontswitch\relax\mathcal G})$, we have the decompositions (the {\bf hexagon relations})
\begin{eqnarray}
    \begin{cases}b_{(VW)X} = a_{XVW} \circ b_{VX} \circ a_{VXW}^\dagger \circ b_{WX}\circ a_{VWX} \\ b_{V(WX)} = a_{WXV}^\dagger \circ b_{VX} \circ a_{WVX} \circ b_{VW} \circ a_{VWX}^\dagger \end{cases}\iff \text{ \eqref{quasirmatrix}},\label{hexag}\\
    \begin{cases}b_{(Vj)X}= a_{XVj} \ast \operatorname{id}_{b_{VX}} \ast a_{VXj}^\dagger \ast b_{jX}\ast a_{VjX} \\ b_{V(jX)} = a_{jXV}^\dagger \ast \operatorname{id}_{b_{VX}} \ast a_{jVX} \ast b_{Vj}\ast a_{VjX}^\dagger \end{cases} \iff \text{apply $D_t^+$ to  \eqref{quasi2rmatrix}},\nonumber\\
    \begin{cases}b_{(iW)k} = a_{kiW} \ast b_{ik} \ast a_{ikW}^\dagger \ast b_{Wk}\ast a_{iWk} \\ b_{i(Wk)} = a_{Wki}^\dagger\ast b_{ik} \ast a_{Wik} \ast b_{iW} \ast a_{iWk}^\dagger\end{cases} \iff \text{ \eqref{quasi2rmatrix}},\nonumber
\end{eqnarray}
as 1-/2-morphisms, and similarly for all the other possible braiding maps on tensor products.

states that we can in fact decompose the top and bottom 1-morphisms in this diagram, provided we keep in mind the hexagonator $\Omega,\Omega^\dagger$  \eqref{hexhomotop} that appears in doing so. We thus obtain a formula of the form
\begin{eqnarray}
    b_{((VW)U)X}&\xRightarrow{\Omega_{(VW)|UX}^\dagger}& a_{X(VW)U}\circ b_{(VW)X} \circ a_{(VW)XU}^\dagger \circ b_{UX}\circ a_{(VW)UX} \nonumber\\
    &\xRightarrow{\Omega_{V|WX}^\dagger}& a_{X(VW)U}\circ \left[a_{XVW}\circ b_{VX} \circ a_{VXW}^\dagger \circ b_{WX} \circ a_{VWX}\right] \nonumber\\
    &\qquad& \circ ~a_{(VW)XU}^\dagger \circ b_{UX}\circ a_{(VW)UX},\label{2.6top}
\end{eqnarray}
and similarly for the bottom 1-morphism $b_{(V(WU))X}$,
\begin{eqnarray}
    b_{(V(WU))X}&\xRightarrow{\Omega_{V|(WU)X}^\dagger}& a_{XV(WU)}\circ b_{VX} \circ a_{VX(WU)}^\dagger \circ b_{(WU)X}\circ a_{V(WU)X} \nonumber\\
    &\xRightarrow{\Omega_{W|UX}^\dagger}& a_{XV(WU)}\circ b_{VX}\circ a_{VX(WU)}^\dagger\nonumber\\
    &\qquad& \circ~ \left[a_{XWU}\circ b_{WX} \circ a_{WXU}^\dagger \circ b_{UX} \circ a_{WUX}\right] \circ a_{V(WU)X}.\label{2.6bot}
\end{eqnarray}
Now notice that there are three identical braiding maps that appear in both of these formulas, $b_{VX},b_{WX},b_{UX}$, but they act on objects that differ by an associator: we have $b_{UX}: (VW)(UX)\rightarrow (VW)(XU)$ from  \eqref{2.6top} and $b_{UX}: V(W(UX))\rightarrow V(W(XU))$ from  \eqref{2.6bot}, for instance. Such a square is precisely given by the diagram  \eqref{assoc2morph},
\begin{equation}
    \begin{tikzcd}
(VW)(UX) \arrow[rr, "a_{VW(UX)}"] \arrow[dd, "b_{UX}"'] &                                   & V(W(UX)) \arrow[dd, "b_{UX}"] \\
                                                            & \xRightarrow{a_{VWb_{UX}}} &                            \\
(VW)(XU) \arrow[rr, "a_{VW(XU)}"]                  &                                   & V(W(XU))                
\end{tikzcd},\nonumber
\end{equation}
and similarly for the other braiding maps that occur in both  \eqref{2.6bot}, \eqref{2.6top}.

\label{classicalstr}
The Lie-ification functor $\mathcal{L}:\mathrm{2Alg}_\mathrm{ass}\rightarrow\mathrm{Lie2Alg}$ lifts to associative 2-algebras (see {\bf Definition \ref{assoc2alg}}), where $\mathfrak g({\@fontswitch\relax\mathcal G}) = \mathcal{L}({\@fontswitch\relax\mathcal G}_{-1})\xrightarrow{t}\mathcal{L}({\@fontswitch\relax\mathcal G}_0)$ is a Lie 2-algebra with
\begin{equation}
    X\rhd Y = X\cdot Y - Y\cdot X,\qquad X=\mathcal{L}(x),~Y=\mathcal{L}(y),\nonumber
\end{equation}
where $x\in{\@fontswitch\relax\mathcal G}_0,y\in{\@fontswitch\relax\mathcal G}_{-1}$. Moreover, the universal enveloping functor $U$ also lifts to Lie 2-algebras $U(\mathfrak g)=U(\mathfrak g_{-1})\xrightarrow{t}U(\mathfrak g_0)$, such that $U$ is left-adjoint to $\mathcal{L}$.

\label{2module2rep}
    Let ${\@fontswitch\relax\mathcal C}\in\textbf{D}$ denote a monoidal category. The 2-category $\operatorname{Mod}_\textbf{D}({\@fontswitch\relax\mathcal C})$ of {\bf ${\@fontswitch\relax\mathcal C}$-modules in $\textbf{D}$} consist of objects ${\@fontswitch\relax\mathcal D}\in \textbf{D}$ equipped with a ${\@fontswitch\relax\mathcal C}$-action 1-morphism $\rhd:{\@fontswitch\relax\mathcal C}\times{\@fontswitch\relax\mathcal D}\rightarrow {\@fontswitch\relax\mathcal D}$ and a set of pseudonatural transformations (the \textit{associators})
\begin{equation}
    \alpha_{XY|{\@fontswitch\relax\mathcal D}}: (X \otimes Y)\rhd - \rightarrow X\rhd(Y\rhd -) \nonumber
\end{equation}
for each $X,Y\in {\@fontswitch\relax\mathcal C}$, satisfying the module pentagon relations up to a possibly non-trivial {\it module pentagonator} 2-morphism $\pi_{XYZ}$. The 1-morphisms are ${\@fontswitch\relax\mathcal C}$-module functors, and the 2-morphisms are ${\@fontswitch\relax\mathcal C}$-module natural transformations.

As foretold, we reconstruct the {module associator} $\alpha$ and {pentagonator} $\pi$ of the ${\@fontswitch\relax\mathcal G}$-modules $V\in \mathsf{2Vect}^{hBC}$ by taking 
\begin{equation}
\alpha_{x_1x_2|V} = \varrho(\rho_0(x_1),\rho_0(x_2))(V),\qquad \pi_{x_1x_2x_3|V} = \mathfrak{T}(\rho_0(x_1),\rho_0(x_2),\rho_0(x_3))(V), \label{pentag2rep}
\end{equation}
where $\rho= (\varrho,\rho_0,\rho_1): {\@fontswitch\relax\mathcal G}\rightarrow \mathfrak{End}(V)$ is a weak 2-representation and $\mathfrak{T}$ is the Hochschild 3-cocycle on $\mathfrak{End}(V)$. We now proceed level by level.

\@startsection
     {paragraph}{4}{\z@}{1ex plus1ex minus.2ex}{-.5em
     plus -.5em minus -.1em}{\reset@font \normalsize\bf}{Objects.} We identify the action 2-functor $\rhd$ as the weak 2-representation $\rho$ such that $x\rhd V = \rho_0(x)V$ for each $x\in {\@fontswitch\relax\mathcal G}_0$. An arrow $x\rhd V\rightarrow x'\rhd V$ is therefore expressed as $\rho_1(y)V$, where $y\in {\@fontswitch\relax\mathcal G}_{-1}$ is interpreted as a 2-morphism $x\xRightarrow{y}x'$ between $x,x'=x+ty$ \cite{Wagemann+2021,Baez:2003fs}, or simply by $\rho_1(y)$. What we need to prove is the pentagon relation between $\alpha,\pi$, as well as the associahedron condition for $\pi$. The pentagon relation can be written as
\begin{equation*}

\begin{tikzcd}
	{((x_1x_2)x_3)\rhd V} & & {(x_1(x_2x_3))\rhd V} & {x_1\rhd((x_2x_3)\rhd V)} \\
	& & {\xRightarrow{\pi_{x_1x_2x_3|V}}} \\
	{(x_1x_2)\rhd(x_3\rhd V)} & & & {x_1\rhd (x_2\rhd(x_3\rhd V)))}
	\arrow["{\rho_1({\@fontswitch\relax\mathcal T}(x_1,x_2,x_3))}", from=1-1, to=1-3]
	\arrow["{\varrho(x_1,x_2x_3)}", from=1-3, to=1-4]
	\arrow["{\varrho(x_1,x_2))\rho_0(x_3)}", from=3-1, to=3-4]
	\arrow["{\varrho(x_1x_2,x_3)}"', from=1-1, to=3-1]
	\arrow["{\rho_0(x_1)\varrho(x_2,x_3)}", from=1-4, to=3-4]
\end{tikzcd}





\end{equation*}
Rewriting $\pi$ in terms of the 3-cocycle $\mathfrak{T}$, we have
\begin{eqnarray}
    \mathfrak{T}(\rho_0(x_1),\rho_0(x_2),\rho_0(x_3)) &=& -\varrho(x_1x_2,x_3) - \varrho(x_1,x_2)\rho_0(x_3) \nonumber\\
    &\qquad& +~ \rho_1({\@fontswitch\relax\mathcal T}(x_1,x_2,x_3)) + \varrho(x_1,x_2x_3) + \rho_0(x_1)\varrho(x_2,x_3),\nonumber
\end{eqnarray}
which is nothing but the last equation of  \eqref{weak2hom}. It is then easy to see that the associahedron condition follows from the Hochschild 3-cocycle condition for $\mathfrak{T}$.


\@startsection
     {paragraph}{4}{\z@}{1ex plus1ex minus.2ex}{-.5em
     plus -.5em minus -.1em}{\reset@font \normalsize\bf}{2-intertwiners.} 
Recall the notion of weak 2-intertwiners that we have given in {\bf Definition \ref{weak2int}}. By treating $V$ as a ${\@fontswitch\relax\mathcal G}$-module 2-category and taking $\rhd,\rhd'$ as the action 2-functors corresponding to the 2-representations $\rho,\rho'$, we equivalently characterize the cochain homotopy $I$ as a collection of invertible natural transformations $I_{\bullet,i}: i(\bullet \rhd V) \Rightarrow \bullet \rhd' i(V)$, such that the following pentagon relation

\[\begin{tikzcd}
	{i(\rho_0(xx’)V)}& && &{\rho’_0(xx’)\circ i(V)} \\
	\\
	{i(\rho_0(x)\rho_0(x’)V)}& & {\rho’_0(x)\circ i(\rho_0(x’)V)} && {\rho’_0(x)\rho’_0(x’)\circ i(V)}
	\arrow["{I_{xx’,i}}", from=1-1, to=1-5]
	\arrow["{i\circ \varrho(x,x’)}"', from=1-1, to=3-1]
	\arrow["{I_{x,i} \otimes\operatorname{id}_{\rho_0(x’)}}", from=3-1, to=3-3]
	\arrow["{\rho’_0(x)\otimes I_{x’,i}}", from=3-3, to=3-5]
	\arrow["{\varrho’(x,x’)\circ i}"', from=3-5, to=1-5]
\end{tikzcd}\]








follows directly from  \eqref{2inthomotopy} This recovers precisely the notion of a ${\@fontswitch\relax\mathcal G}$-module functor \cite{Delcamp:2023kew}. Notice no pentagonator appears here, as this is a relation on the 2-morphisms in $\operatorname{2Rep}^{\@fontswitch\relax\mathcal T}({\@fontswitch\relax\mathcal G})$ and hence a pentagonator for it would have to be a 3-morphism. 


\@startsection
     {paragraph}{4}{\z@}{1ex plus1ex minus.2ex}{-.5em
     plus -.5em minus -.1em}{\reset@font \normalsize\bf}{Modifications.}
Now let us consider the notion of modifications in $\operatorname{2Rep}^{\@fontswitch\relax\mathcal T}({\@fontswitch\relax\mathcal G})$ we have defined in {\bf Definition \ref{weakmodif}}. The condition  \eqref{modifhomotopy} is equivalent to the composition of 2-morphisms $(\operatorname{id}_{\rho_0(x)}\mu)\ast I_{x,i} = I_{x,i'}\ast \mu$, which is exactly a module natural transformation \cite{Delcamp:2023kew}.
